pub(super) async fn inspect_lifecycle_metadata<IndexAdapter>(
    index_store: &IndexAdapter,
    object_root: &Path,
    object_store: &ServerObjectStore,
    reachability: &FsckReachability,
    report: &mut FsckReport,
) -> Result<(), FsckError>
where
    IndexAdapter: AsyncIndexStore + Sync,
    IndexAdapter::Error: Into<FsckError>,
{
    let now_unix_seconds = unix_now_seconds_checked()?;
    let mut quarantined_object_keys = HashSet::new();

    index_store
        .visit_quarantine_candidates(|candidate| {
            let object_key = candidate.object_key();
            let object_key_string = object_key.as_str().to_owned();
            quarantined_object_keys.insert(object_key_string.clone());
            let location = object_location_display(object_root, object_store, object_key);

            if candidate.delete_after_unix_seconds()
                < candidate.first_seen_unreachable_at_unix_seconds()
            {
                push_issue(
                    report,
                    FsckIssueKind::InvalidQuarantineCandidate,
                    location.clone(),
                    FsckIssueDetail::InvalidQuarantineTimeline {
                        delete_after_unix_seconds: candidate.delete_after_unix_seconds(),
                        first_seen_unreachable_at_unix_seconds: candidate
                            .first_seen_unreachable_at_unix_seconds(),
                    },
                )?;
            }

            match object_store.metadata(object_key)? {
                Some(metadata) => {
                    if metadata.length() != candidate.observed_length() {
                        push_issue(
                            report,
                            FsckIssueKind::QuarantineLengthMismatch,
                            location.clone(),
                            FsckIssueDetail::LengthMismatch {
                                expected_length: candidate.observed_length(),
                                observed_length: metadata.length(),
                            },
                        )?;
                    }
                }
                None => {
                    push_issue(
                        report,
                        FsckIssueKind::MissingQuarantinedObject,
                        location.clone(),
                        FsckIssueDetail::QuarantineReferencedMissingObject,
                    )?;
                }
            }

            if reachability
                .referenced_object_keys
                .contains(&object_key_string)
            {
                push_issue(
                    report,
                    FsckIssueKind::ReachableQuarantinedObject,
                    location,
                    FsckIssueDetail::QuarantineTargetedReachableObject,
                )?;
            }
            Ok::<(), FsckError>(())
        })
        .await?;

    index_store
        .visit_retention_holds(|hold| {
            let object_key = hold.object_key();
            let object_key_string = object_key.as_str().to_owned();
            let location = object_location_display(object_root, object_store, object_key);

            if let Some(release_after_unix_seconds) = hold.release_after_unix_seconds()
                && release_after_unix_seconds < hold.held_at_unix_seconds()
            {
                push_issue(
                    report,
                    FsckIssueKind::InvalidRetentionHold,
                    location.clone(),
                    FsckIssueDetail::InvalidRetentionTimeline {
                        release_after_unix_seconds,
                        held_at_unix_seconds: hold.held_at_unix_seconds(),
                    },
                )?;
            }

            if hold.is_active_at(now_unix_seconds) {
                if object_store.metadata(object_key)?.is_none() {
                    push_issue(
                        report,
                        FsckIssueKind::MissingHeldObject,
                        location.clone(),
                        FsckIssueDetail::ActiveRetentionHoldReason {
                            reason: hold.reason().to_owned(),
                        },
                    )?;
                }
                if quarantined_object_keys.contains(&object_key_string) {
                    push_issue(
                        report,
                        FsckIssueKind::HeldQuarantinedObject,
                        location,
                        FsckIssueDetail::ActiveRetentionHoldQuarantined,
                    )?;
                }
            }
            Ok::<(), FsckError>(())
        })
        .await?;

    let max_processed_at_unix_seconds = now_unix_seconds
        .checked_add(WEBHOOK_DELIVERY_FUTURE_SKEW_SECONDS)
        .ok_or(FsckError::Overflow)?;
    let max_provider_state_timestamp = max_processed_at_unix_seconds;
    index_store
        .visit_webhook_deliveries(|delivery| {
            report.inspected_webhook_deliveries =
                checked_increment(report.inspected_webhook_deliveries)?;
            if delivery.processed_at_unix_seconds() > max_processed_at_unix_seconds {
                push_issue(
                    report,
                    FsckIssueKind::InvalidWebhookDeliveryTimestamp,
                    format!(
                        "{}/{}",
                        provider_directory(delivery.provider()),
                        delivery.delivery_id()
                    ),
                    FsckIssueDetail::WebhookDeliveryTimestampExceeded {
                        processed_at_unix_seconds: delivery.processed_at_unix_seconds(),
                        max_allowed_unix_seconds: max_processed_at_unix_seconds,
                    },
                )?;
            }
            Ok::<(), FsckError>(())
        })
        .await?;

    index_store
        .visit_provider_repository_states(|state| {
            report.inspected_provider_repository_states =
                checked_increment(report.inspected_provider_repository_states)?;
            let location = format!(
                "{}/{}/{}",
                provider_directory(state.provider()),
                state.owner(),
                state.repo()
            );
            if RepositoryScope::new(state.provider(), state.owner(), state.repo(), None).is_err() {
                push_issue(
                    report,
                    FsckIssueKind::InvalidProviderRepositoryState,
                    location.clone(),
                    FsckIssueDetail::ProviderRepositoryIdentityInvalid,
                )?;
            }
            inspect_provider_state_timestamp(
                report,
                &location,
                ProviderRepositoryStateTimestampField::LastAccessChangedAtUnixSeconds,
                state.last_access_changed_at_unix_seconds(),
                max_provider_state_timestamp,
            )?;
            inspect_provider_state_timestamp(
                report,
                &location,
                ProviderRepositoryStateTimestampField::LastRevisionPushedAtUnixSeconds,
                state.last_revision_pushed_at_unix_seconds(),
                max_provider_state_timestamp,
            )?;
            inspect_provider_state_timestamp(
                report,
                &location,
                ProviderRepositoryStateTimestampField::LastCacheInvalidatedAtUnixSeconds,
                state.last_cache_invalidated_at_unix_seconds(),
                max_provider_state_timestamp,
            )?;
            inspect_provider_state_timestamp(
                report,
                &location,
                ProviderRepositoryStateTimestampField::LastAuthorizationRecheckedAtUnixSeconds,
                state.last_authorization_rechecked_at_unix_seconds(),
                max_provider_state_timestamp,
            )?;
            inspect_provider_state_timestamp(
                report,
                &location,
                ProviderRepositoryStateTimestampField::LastDriftCheckedAtUnixSeconds,
                state.last_drift_checked_at_unix_seconds(),
                max_provider_state_timestamp,
            )?;
            Ok::<(), FsckError>(())
        })
        .await?;

    Ok(())
}

fn inspect_provider_state_timestamp(
    report: &mut FsckReport,
    location: &str,
    field: ProviderRepositoryStateTimestampField,
    timestamp: Option<u64>,
    max_allowed_unix_seconds: u64,
) -> Result<(), FsckError> {
    let Some(timestamp) = timestamp else {
        return Ok(());
    };
    if timestamp > max_allowed_unix_seconds {
        push_issue(
            report,
            FsckIssueKind::InvalidProviderRepositoryStateTimestamp,
            location.to_owned(),
            FsckIssueDetail::ProviderRepositoryStateTimestampExceeded {
                field,
                timestamp,
                max_allowed_unix_seconds,
            },
        )?;
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn clean_report() -> FsckReport {
        FsckReport {
            latest_records: 0,
            version_records: 0,
            inspected_chunk_references: 0,
            inspected_dedupe_shard_mappings: 0,
            inspected_reconstructions: 0,
            inspected_webhook_deliveries: 0,
            inspected_provider_repository_states: 0,
            issues: Vec::new(),
        }
    }

    fn empty_reachability() -> FsckReachability {
        FsckReachability {
            referenced_object_keys: HashSet::new(),
            live_dedupe_chunk_hashes: HashSet::new(),
        }
    }

    fn make_key(path: &str) -> shardline_storage::ObjectKey {
        shardline_storage::ObjectKey::parse(path).unwrap()
    }

    // ── inspect_provider_state_timestamp ────────────────────────────────

    #[test]
    fn provider_state_timestamp_none_is_ok() {
        let mut report = clean_report();
        inspect_provider_state_timestamp(
            &mut report,
            "test/loc",
            ProviderRepositoryStateTimestampField::LastAccessChangedAtUnixSeconds,
            None,
            100,
        )
        .unwrap();
        assert!(report.is_clean());
    }

    #[test]
    fn provider_state_timestamp_within_bounds_is_ok() {
        let mut report = clean_report();
        inspect_provider_state_timestamp(
            &mut report,
            "test/loc",
            ProviderRepositoryStateTimestampField::LastAccessChangedAtUnixSeconds,
            Some(50),
            100,
        )
        .unwrap();
        assert!(report.is_clean());
    }

    #[allow(clippy::panic, clippy::wildcard_enum_match_arm)]
    #[test]
    fn provider_state_timestamp_exceeding_max_creates_issue() {
        let mut report = clean_report();
        inspect_provider_state_timestamp(
            &mut report,
            "test/loc",
            ProviderRepositoryStateTimestampField::LastRevisionPushedAtUnixSeconds,
            Some(200),
            100,
        )
        .unwrap();
        assert_eq!(report.issue_count(), 1);
        assert_eq!(
            report.issues[0].kind,
            FsckIssueKind::InvalidProviderRepositoryStateTimestamp
        );
        assert_eq!(report.issues[0].location, "test/loc");
        match &report.issues[0].detail {
            FsckIssueDetail::ProviderRepositoryStateTimestampExceeded {
                field,
                timestamp,
                max_allowed_unix_seconds,
            } => {
                assert_eq!(
                    *field,
                    ProviderRepositoryStateTimestampField::LastRevisionPushedAtUnixSeconds
                );
                assert_eq!(*timestamp, 200);
                assert_eq!(*max_allowed_unix_seconds, 100);
            }
            other => panic!("unexpected detail: {other:?}"),
        }
    }

    // ── inspect_lifecycle_metadata ──────────────────────────────────────

    /// Helper: create stores, run inspect_lifecycle_metadata, return report.
    async fn run_lifecycle_check(
        index_store: &shardline_index::MemoryIndexStore,
        reachability: Option<FsckReachability>,
    ) -> FsckReport {
        let object_root = std::path::Path::new("/tmp");
        let object_store = ServerObjectStore::blackhole();
        let mut report = clean_report();
        let reach = reachability.unwrap_or_else(empty_reachability);
        inspect_lifecycle_metadata(index_store, object_root, &object_store, &reach, &mut report)
            .await
            .unwrap();
        report
    }

    #[tokio::test]
    async fn lifecycle_clean_with_no_data() {
        let store = shardline_index::MemoryIndexStore::new();
        let report = run_lifecycle_check(&store, None).await;
        assert!(report.is_clean());
        assert_eq!(report.inspected_webhook_deliveries, 0);
        assert_eq!(report.inspected_provider_repository_states, 0);
    }

    #[tokio::test]
    async fn quarantine_missing_object_detected() {
        use shardline_index::LifecycleStore;
        let store = shardline_index::MemoryIndexStore::new();
        let obj_key = make_key("ab/1234");
        let candidate =
            shardline_index::QuarantineCandidate::new(obj_key.clone(), 100, 100, 200).unwrap();
        LifecycleStore::upsert_quarantine_candidate(&store, &candidate).unwrap();
        // blackhole store returns None for metadata => MissingQuarantinedObject
        let report = run_lifecycle_check(&store, None).await;
        assert_eq!(report.issue_count(), 1);
        assert_eq!(
            report.issues[0].kind,
            FsckIssueKind::MissingQuarantinedObject
        );
    }

    #[tokio::test]
    async fn quarantined_reachable_object_detected() {
        use shardline_index::LifecycleStore;
        let store = shardline_index::MemoryIndexStore::new();
        let obj_key = make_key("ab/1234");
        let candidate =
            shardline_index::QuarantineCandidate::new(obj_key.clone(), 100, 100, 200).unwrap();
        LifecycleStore::upsert_quarantine_candidate(&store, &candidate).unwrap();
        let mut reach = empty_reachability();
        reach
            .referenced_object_keys
            .insert("ab/1234".to_owned());
        let report = run_lifecycle_check(&store, Some(reach)).await;
        // 1 missing object (blackhole) + 1 reachable
        assert_eq!(report.issue_count(), 2);
        assert_eq!(
            report.issues[1].kind,
            FsckIssueKind::ReachableQuarantinedObject
        );
    }

    #[tokio::test]
    async fn retention_hold_missing_object_detected() {
        use shardline_index::LifecycleStore;
        let store = shardline_index::MemoryIndexStore::new();
        let obj_key = make_key("ab/1234");
        // Active hold (no release_after = permanently active) with missing object
        let hold = shardline_index::RetentionHold::new(
            obj_key.clone(),
            "test-reason".to_owned(),
            100,
            None, // no release = always active
        )
        .unwrap();
        LifecycleStore::upsert_retention_hold(&store, &hold).unwrap();
        let report = run_lifecycle_check(&store, None).await;
        assert_eq!(report.issue_count(), 1);
        assert_eq!(report.issues[0].kind, FsckIssueKind::MissingHeldObject);
    }

    #[tokio::test]
    async fn held_quarantined_object_detected() {
        use shardline_index::LifecycleStore;
        let store = shardline_index::MemoryIndexStore::new();
        let obj_key = make_key("ab/1234");
        let candidate =
            shardline_index::QuarantineCandidate::new(obj_key.clone(), 100, 100, 200).unwrap();
        LifecycleStore::upsert_quarantine_candidate(&store, &candidate).unwrap();
        let hold = shardline_index::RetentionHold::new(
            obj_key.clone(),
            "reason".to_owned(),
            100,
            None,
        )
        .unwrap();
        LifecycleStore::upsert_retention_hold(&store, &hold).unwrap();
        let report = run_lifecycle_check(&store, None).await;
        // 1 missing object (quarantine) + 1 held+quarantined
        let held_quarantined = report
            .issues
            .iter()
            .filter(|i| i.kind == FsckIssueKind::HeldQuarantinedObject)
            .count();
        assert_eq!(held_quarantined, 1);
    }

    #[tokio::test]
    async fn webhook_delivery_future_timestamp_detected() {
        use shardline_index::LifecycleStore;
        let store = shardline_index::MemoryIndexStore::new();
        let delivery = shardline_index::WebhookDelivery::new(
            shardline_protocol::RepositoryProvider::GitHub,
            "owner".to_owned(),
            "repo".to_owned(),
            "delivery-1".to_owned(),
            u64::MAX,
        )
        .unwrap();
        LifecycleStore::record_webhook_delivery(&store, &delivery).unwrap();
        let report = run_lifecycle_check(&store, None).await;
        assert_eq!(report.issue_count(), 1);
        assert_eq!(
            report.issues[0].kind,
            FsckIssueKind::InvalidWebhookDeliveryTimestamp
        );
    }

    #[tokio::test]
    async fn provider_state_invalid_identity_detected() {
        use shardline_index::LifecycleStore;
        let store = shardline_index::MemoryIndexStore::new();
        // Empty owner + repo creates an invalid RepositoryScope
        let state = shardline_index::ProviderRepositoryState::new(
            shardline_protocol::RepositoryProvider::GitHub,
            String::new(),
            String::new(),
            None,
            None,
            None,
        );
        LifecycleStore::upsert_provider_repository_state(&store, &state).unwrap();
        let report = run_lifecycle_check(&store, None).await;
        let count = report
            .issues
            .iter()
            .filter(|i| i.kind == FsckIssueKind::InvalidProviderRepositoryState)
            .count();
        assert_eq!(count, 1);
    }
}

use std::{io::Cursor, path::Path};

use shardline_index::{
    FileChunkRecord, FileRecord, RecordTraversal, StoredRecord, parse_xet_hash_hex,
    xet_hash_hex_string,
};
use shardline_server_core::{
    OpsRecordStore, ServerObjectStore, checked_add, checked_increment, chunk_hash,
    chunk_object_key, content_hash, parse_stored_file_record_bytes, read_full_object,
    validate_content_hash, validate_identifier,
};
use shardline_storage::ObjectStore;
use shardline_xet_adapter::{
    XorbVisitError, try_for_each_serialized_xorb_chunk, validate_serialized_xorb, xorb_object_key,
};

use super::{
    FsckError, FsckIssueDetail, FsckIssueKind, FsckObjectContext, FsckReachability, FsckReport,
    PendingVersionRecordCheck, RecordKind, object_location_display, push_issue,
    push_reconstruction_plan_issue, record_path,
};

fn map_xorb_visit_error_fsck(error: XorbVisitError<FsckError>) -> FsckError {
    match error {
        XorbVisitError::Parse(error) => FsckError::from(error),
        XorbVisitError::Visitor(error) => error,
    }
}

pub(super) async fn scan_record_tree<RecordAdapter>(
    record_store: &RecordAdapter,
    record_kind: RecordKind,
    object_root: &Path,
    object_store: &ServerObjectStore,
    reachability: &mut FsckReachability,
    report: &mut FsckReport,
) -> Result<(), FsckError>
where
    RecordAdapter: OpsRecordStore + Sync,
    RecordAdapter::Error: Into<FsckError>,
{
    let object_context = FsckObjectContext {
        object_root,
        object_store,
    };
    match record_kind {
        RecordKind::Latest => {
            let mut pending_version_record_checks = Vec::new();
            RecordTraversal::visit_latest_records(record_store, |entry| {
                report.latest_records = checked_increment(report.latest_records)?;
                inspect_latest_record(
                    record_store,
                    entry,
                    &object_context,
                    reachability,
                    &mut pending_version_record_checks,
                    report,
                )
            })
            .await?;

            for check in pending_version_record_checks {
                if !RecordTraversal::record_locator_exists(record_store, &check.version_locator)
                    .await
                    .map_err(Into::into)?
                {
                    push_issue(
                        report,
                        FsckIssueKind::MissingVersionRecord,
                        record_store.locator_display(&check.latest_locator),
                        FsckIssueDetail::MissingVersionRecord {
                            version_locator: record_store.locator_display(&check.version_locator),
                        },
                    )?;
                    continue;
                }

                inspect_matching_version_record(record_store, &check, report).await?;
            }

            Ok(())
        }
        RecordKind::Version => {
            RecordTraversal::visit_version_records(record_store, |entry| {
                report.version_records = checked_increment(report.version_records)?;
                let _record = inspect_record_bytes(
                    record_store,
                    &entry,
                    RecordKind::Version,
                    &object_context,
                    reachability,
                    report,
                )?;
                Ok(())
            })
            .await
        }
    }
}

fn inspect_latest_record<RecordAdapter>(
    record_store: &RecordAdapter,
    entry: StoredRecord<RecordAdapter::Locator>,
    object_context: &FsckObjectContext<'_>,
    reachability: &mut FsckReachability,
    pending_version_record_checks: &mut Vec<PendingVersionRecordCheck<RecordAdapter::Locator>>,
    report: &mut FsckReport,
) -> Result<(), FsckError>
where
    RecordAdapter: OpsRecordStore,
    RecordAdapter::Error: Into<FsckError>,
{
    let Some(record) = inspect_record_bytes(
        record_store,
        &entry,
        RecordKind::Latest,
        object_context,
        reachability,
        report,
    )?
    else {
        return Ok(());
    };
    let StoredRecord {
        locator: path,
        bytes: _bytes,
        modified_since_epoch: _modified_since_epoch,
    } = entry;

    pending_version_record_checks.push(PendingVersionRecordCheck {
        latest_locator: path,
        version_locator: record_store.version_record_locator(&record),
        latest_record: record,
    });

    Ok(())
}

fn inspect_record_bytes<RecordAdapter>(
    record_store: &RecordAdapter,
    entry: &StoredRecord<RecordAdapter::Locator>,
    record_kind: RecordKind,
    object_context: &FsckObjectContext<'_>,
    reachability: &mut FsckReachability,
    report: &mut FsckReport,
) -> Result<Option<FileRecord>, FsckError>
where
    RecordAdapter: OpsRecordStore,
{
    let path = &entry.locator;
    let bytes = &entry.bytes;
    let record_location = record_store.locator_display(path);
    let record = match parse_stored_file_record_bytes(bytes) {
        Ok(record) => record,
        Err(shardline_server_core::ParseStoredFileRecordError::StoredFileMetadataTooLarge {
            ..
        }) => {
            push_issue(
                report,
                FsckIssueKind::OversizedRecordMetadata,
                record_location,
                FsckIssueDetail::OversizedRecordMetadata,
            )?;
            return Ok(None);
        }
        Err(shardline_server_core::ParseStoredFileRecordError::Json(_)) => {
            push_issue(
                report,
                FsckIssueKind::InvalidRecordJson,
                record_location,
                FsckIssueDetail::RecordJsonInvalid,
            )?;
            return Ok(None);
        }
    };

    if validate_identifier(&record.file_id).is_err() {
        push_issue(
            report,
            FsckIssueKind::InvalidFileId,
            record_store.locator_display(path),
            FsckIssueDetail::InvalidFileId {
                file_id: record.file_id.clone(),
            },
        )?;
    }

    if validate_content_hash(&record.content_hash).is_err() {
        push_issue(
            report,
            FsckIssueKind::InvalidContentHash,
            record_store.locator_display(path),
            FsckIssueDetail::InvalidContentHash {
                content_hash: record.content_hash.clone(),
            },
        )?;
    }

    let expected_path = record_path(record_store, record_kind, &record);
    if expected_path != *path {
        push_issue(
            report,
            FsckIssueKind::RecordPathMismatch,
            record_store.locator_display(path),
            FsckIssueDetail::RecordPathMismatch {
                expected_locator: record_store.locator_display(&expected_path),
            },
        )?;
    }

    let expected_file_id = record_store.locator_file_id(path, record_kind.ops());
    if expected_file_id.as_deref() != Some(record.file_id.as_str()) {
        push_issue(
            report,
            FsckIssueKind::RecordPathMismatch,
            record_store.locator_display(path),
            FsckIssueDetail::RecordFileIdPathMismatch,
        )?;
    }

    if record_kind == RecordKind::Version {
        let expected_hash = record_store.locator_content_hash(path, record_kind.ops());
        if expected_hash.as_deref() != Some(record.content_hash.as_str()) {
            push_issue(
                report,
                FsckIssueKind::RecordPathMismatch,
                record_store.locator_display(path),
                FsckIssueDetail::RecordContentHashPathMismatch,
            )?;
        }
    }

    if let Err(error) = record.validate_reconstruction_plan() {
        push_reconstruction_plan_issue(report, record_store.locator_display(path), &error)?;
        return Ok(Some(record));
    }

    inspect_chunks(
        object_context.object_root,
        &record_location,
        &record,
        object_context.object_store,
        reachability,
        report,
    )?;

    Ok(Some(record))
}

fn inspect_chunks(
    object_root: &Path,
    record_location: &str,
    record: &FileRecord,
    object_store: &ServerObjectStore,
    reachability: &mut FsckReachability,
    report: &mut FsckReport,
) -> Result<(), FsckError> {
    for chunk in &record.chunks {
        report.inspected_chunk_references = checked_increment(report.inspected_chunk_references)?;

        if record.chunk_size == 0 {
            inspect_native_xet_term(
                object_root,
                object_store,
                record_location,
                chunk,
                reachability,
                report,
            )?;
            continue;
        }

        let object_key = match chunk_object_key(&chunk.hash) {
            Ok(object_key) => object_key,
            Err(_) => {
                push_issue(
                    report,
                    FsckIssueKind::InvalidContentHash,
                    record_location.to_owned(),
                    FsckIssueDetail::InvalidChunkHash {
                        chunk_hash: chunk.hash.clone(),
                    },
                )?;
                continue;
            }
        };
        reachability
            .referenced_object_keys
            .insert(object_key.as_str().to_owned());
        reachability
            .live_dedupe_chunk_hashes
            .insert(chunk.hash.clone());
        let optional_xorb_key = xorb_object_key(&chunk.hash)?;
        if object_store.metadata(&optional_xorb_key)?.is_some() {
            reachability
                .referenced_object_keys
                .insert(optional_xorb_key.as_str().to_owned());
        }

        let chunk_location = object_location_display(object_root, object_store, &object_key);
        let metadata = match object_store.metadata(&object_key)? {
            Some(metadata) => metadata,
            None => {
                push_issue(
                    report,
                    FsckIssueKind::MissingChunk,
                    chunk_location.clone(),
                    FsckIssueDetail::ReferencedByRecord {
                        record_location: record_location.to_owned(),
                    },
                )?;
                continue;
            }
        };

        let chunk_bytes = read_full_object(object_store, &object_key, metadata.length())?;
        let actual_hash = xet_hash_hex_string(chunk_hash(&chunk_bytes));
        if actual_hash != chunk.hash {
            push_issue(
                report,
                FsckIssueKind::ChunkHashMismatch,
                chunk_location.clone(),
                FsckIssueDetail::HashMismatch {
                    expected_hash: chunk.hash.clone(),
                    observed_hash: actual_hash,
                },
            )?;
        }

        let actual_length = metadata.length();
        if actual_length != chunk.length {
            push_issue(
                report,
                FsckIssueKind::ChunkLengthMismatch,
                chunk_location,
                FsckIssueDetail::LengthMismatch {
                    expected_length: chunk.length,
                    observed_length: actual_length,
                },
            )?;
        }
    }

    let computed_content_hash = content_hash(record.total_bytes, record.chunk_size, &record.chunks);
    if computed_content_hash != record.content_hash {
        push_issue(
            report,
            FsckIssueKind::RecordHashMismatch,
            record_location.to_owned(),
            FsckIssueDetail::HashMismatch {
                expected_hash: record.content_hash.clone(),
                observed_hash: computed_content_hash,
            },
        )?;
    }

    Ok(())
}

fn inspect_native_xet_term(
    object_root: &Path,
    object_store: &ServerObjectStore,
    record_location: &str,
    chunk: &FileChunkRecord,
    reachability: &mut FsckReachability,
    report: &mut FsckReport,
) -> Result<(), FsckError> {
    let object_key = match xorb_object_key(&chunk.hash) {
        Ok(object_key) => object_key,
        Err(_) => {
            push_issue(
                report,
                FsckIssueKind::InvalidContentHash,
                record_location.to_owned(),
                FsckIssueDetail::InvalidXorbHash {
                    xorb_hash: chunk.hash.clone(),
                },
            )?;
            return Ok(());
        }
    };
    reachability
        .referenced_object_keys
        .insert(object_key.as_str().to_owned());

    let xorb_location = object_location_display(object_root, object_store, &object_key);
    let metadata = match object_store.metadata(&object_key)? {
        Some(metadata) => metadata,
        None => {
            push_issue(
                report,
                FsckIssueKind::MissingChunk,
                xorb_location,
                FsckIssueDetail::ReferencedByNativeXetRecord {
                    record_location: record_location.to_owned(),
                },
            )?;
            return Ok(());
        }
    };

    let xorb_bytes = read_full_object(object_store, &object_key, metadata.length())?;
    let expected_hash = parse_xet_hash_hex(&chunk.hash)?;
    let mut reader = Cursor::new(xorb_bytes);
    let validated = validate_serialized_xorb(&mut reader, expected_hash)?;
    let range_start = usize::try_from(chunk.range_start)?;
    let range_end = usize::try_from(chunk.range_end)?;
    if range_end > validated.chunks().len() {
        push_issue(
            report,
            FsckIssueKind::ChunkLengthMismatch,
            xorb_location,
            FsckIssueDetail::XorbRangeExceededChunkCount {
                range_start: chunk.range_start,
                range_end: chunk.range_end,
                chunk_count: validated.chunks().len(),
            },
        )?;
        return Ok(());
    }

    let mut actual_length = 0_u64;
    let mut chunk_index = 0_usize;
    try_for_each_serialized_xorb_chunk(&mut reader, &validated, |decoded_chunk| {
        if chunk_index < range_start || chunk_index >= range_end {
            chunk_index = chunk_index.checked_add(1).ok_or(FsckError::Overflow)?;
            return Ok::<(), FsckError>(());
        }

        let unpacked_length = u64::try_from(decoded_chunk.data().len())?;
        actual_length = checked_add(actual_length, unpacked_length)?;

        let chunk_hash_hex = xet_hash_hex_string(decoded_chunk.descriptor().hash());
        let chunk_object_key = chunk_object_key(&chunk_hash_hex)?;
        reachability
            .referenced_object_keys
            .insert(chunk_object_key.as_str().to_owned());
        let chunk_location = object_location_display(object_root, object_store, &chunk_object_key);
        let chunk_metadata = match object_store.metadata(&chunk_object_key)? {
            Some(chunk_metadata) => chunk_metadata,
            None => {
                push_issue(
                    report,
                    FsckIssueKind::MissingChunk,
                    chunk_location,
                    FsckIssueDetail::ReferencedByNativeXetXorb {
                        xorb_location: xorb_location.clone(),
                    },
                )?;
                chunk_index = chunk_index.checked_add(1).ok_or(FsckError::Overflow)?;
                return Ok(());
            }
        };

        let chunk_bytes =
            read_full_object(object_store, &chunk_object_key, chunk_metadata.length())?;
        let actual_chunk_hash = xet_hash_hex_string(chunk_hash(&chunk_bytes));
        if actual_chunk_hash != chunk_hash_hex {
            push_issue(
                report,
                FsckIssueKind::ChunkHashMismatch,
                chunk_location.clone(),
                FsckIssueDetail::HashMismatch {
                    expected_hash: chunk_hash_hex,
                    observed_hash: actual_chunk_hash,
                },
            )?;
        }
        if chunk_metadata.length() != unpacked_length {
            push_issue(
                report,
                FsckIssueKind::ChunkLengthMismatch,
                chunk_location,
                FsckIssueDetail::LengthMismatch {
                    expected_length: unpacked_length,
                    observed_length: chunk_metadata.length(),
                },
            )?;
        }

        chunk_index = chunk_index.checked_add(1).ok_or(FsckError::Overflow)?;
        Ok(())
    })
    .map_err(map_xorb_visit_error_fsck)?;
    if actual_length != chunk.length {
        push_issue(
            report,
            FsckIssueKind::ChunkLengthMismatch,
            object_location_display(object_root, object_store, &object_key),
            FsckIssueDetail::LengthMismatch {
                expected_length: chunk.length,
                observed_length: actual_length,
            },
        )?;
    }

    Ok(())
}

async fn inspect_matching_version_record<RecordAdapter>(
    record_store: &RecordAdapter,
    check: &PendingVersionRecordCheck<RecordAdapter::Locator>,
    report: &mut FsckReport,
) -> Result<(), FsckError>
where
    RecordAdapter: OpsRecordStore + Sync,
    RecordAdapter::Error: Into<FsckError>,
{
    let version_bytes = RecordTraversal::read_record_bytes(record_store, &check.version_locator)
        .await
        .map_err(Into::into)?;
    let version_record = match parse_stored_file_record_bytes(&version_bytes) {
        Ok(record) => record,
        Err(shardline_server_core::ParseStoredFileRecordError::StoredFileMetadataTooLarge {
            ..
        }) => {
            push_issue(
                report,
                FsckIssueKind::OversizedRecordMetadata,
                record_store.locator_display(&check.version_locator),
                FsckIssueDetail::OversizedRecordMetadata,
            )?;
            return Ok(());
        }
        Err(_error) => {
            return Ok(());
        }
    };
    if version_record != check.latest_record {
        push_issue(
            report,
            FsckIssueKind::MismatchedVersionRecord,
            record_store.locator_display(&check.latest_locator),
            FsckIssueDetail::MismatchedVersionRecord {
                version_locator: record_store.locator_display(&check.version_locator),
            },
        )?;
    }

    Ok(())
}

#![no_main]
#![allow(
    clippy::arithmetic_side_effects,
    clippy::indexing_slicing,
    clippy::redundant_clone,
    clippy::shadow_unrelated
)]

use std::{
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    thread,
};

use bytes::Bytes;
use futures_util::TryStreamExt;
use libfuzzer_sys::fuzz_target;
use object_store::{
    CopyMode, CopyOptions, GetOptions, ObjectStore as _, ObjectStoreExt, PutMode, memory::InMemory,
    path::Path as ObjectStorePath,
};
use shardline_protocol::{ByteRange, ShardlineHash};
use shardline_storage::{
    LocalObjectStore, LocalObjectStoreError, ObjectBody, ObjectIntegrity, ObjectKey, ObjectStore,
    PutOutcome,
};

const MAX_BODY_BYTES: usize = 256;
const CONCURRENT_WRITERS: usize = 4;

fuzz_target!(|data: (u8, Vec<u8>)| {
    let (op, mut body) = data;
    body.truncate(MAX_BODY_BYTES);
    if body.is_empty() {
        body.push(0);
    }

    let hash = ShardlineHash::from_bytes(*blake3::hash(&body).as_bytes());
    let integrity = ObjectIntegrity::new(hash, body.len() as u64);

    match op % 12 {
        0 => local_concurrent_put_same_key_same_body(&body, &integrity),
        1 => local_concurrent_put_same_key_different_body(&body),
        2 => local_concurrent_put_and_read(&body, &integrity),
        3 => async_concurrent_put_same_key_same_body(&body, &integrity),
        4 => async_toctou_race_check_then_put(&body, &integrity),
        5 => async_concurrent_put_different_bytes(&body),
        6 => async_concurrent_delete_and_put(&body, &integrity),
        7 => async_list_consistency_during_writes(&body, &integrity),
        8 => local_concurrent_contains_and_put(&body, &integrity),
        9 => async_concurrent_copy_race(&body, &integrity),
        10 => local_concurrent_delete_and_put(&body, &integrity),
        11 => async_toctou_multipart_race(&body, &integrity),
        _ => {}
    }
});

fn create_local_store() -> Option<(tempfile::TempDir, LocalObjectStore)> {
    let sandbox = tempfile::tempdir().ok()?;
    let root = sandbox.path().join("objects");
    let store = LocalObjectStore::new(root).ok()?;
    Some((sandbox, store))
}

fn create_key(seed: &[u8]) -> Option<ObjectKey> {
    let h = blake3::hash(seed);
    let hex = hex::encode(h.as_bytes());
    let key_str = format!("aa/{hex}.obj");
    ObjectKey::parse(&key_str).ok()
}

fn spawn_concurrent_writers<F>(count: usize, f: F)
where
    F: Fn(usize) + Send + Clone + 'static,
{
    let mut threads = Vec::with_capacity(count);
    for i in 0..count {
        let f = f.clone();
        threads.push(thread::spawn(move || f(i)));
    }
    for t in threads {
        let _j = t.join();
    }
}

fn range_up_to(length: u64) -> Option<ByteRange> {
    if length == 0 {
        return None;
    }
    let end = length.checked_sub(1)?;
    ByteRange::new(0, end).ok()
}

fn build_rt() -> Option<tokio::runtime::Runtime> {
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .ok()
}

fn local_concurrent_put_same_key_same_body(body: &[u8], integrity: &ObjectIntegrity) {
    let Some((_sandbox, store)) = create_local_store() else {
        return;
    };
    let store = Arc::new(store);
    let Some(key) = create_key(body) else { return };
    let body = body.to_vec();

    let outcomes: Arc<std::sync::Mutex<Vec<PutOutcome>>> = Arc::default();
    let store_writer = store.clone();
    let key_writer = key.clone();
    let body_writer = body.clone();
    let outcomes_writer = outcomes.clone();
    let integrity_writer = *integrity;
    spawn_concurrent_writers(CONCURRENT_WRITERS, move |_i| {
        if let Ok(result) = store_writer.put_if_absent(
            &key_writer,
            ObjectBody::from_slice(&body_writer),
            &integrity_writer,
        ) && let Ok(mut guard) = outcomes_writer.lock()
        {
            guard.push(result);
        }
    });

    let inserted = outcomes.lock().map_or(0, |guard| {
        guard.iter().filter(|o| **o == PutOutcome::Inserted).count()
    });
    let exists = outcomes.lock().map_or(0, |guard| {
        guard
            .iter()
            .filter(|o| **o == PutOutcome::AlreadyExists)
            .count()
    });
    let total = outcomes.lock().map_or(0, |guard| guard.len());
    assert!(
        inserted <= 1,
        "concurrent put_if_absent for same key with same body: \
         expected at most 1 Inserted, got {inserted}"
    );
    assert_eq!(
        inserted.wrapping_add(exists),
        total,
        "all outcomes must be Inserted or AlreadyExists"
    );
    if let Some(range) = range_up_to(body.len() as u64)
        && let Ok(bytes) = store.read_range(&key, range)
    {
        assert_eq!(bytes, body, "stored bytes must match");
    }
}

fn local_concurrent_put_same_key_different_body(body: &[u8]) {
    let Some((_sandbox, store)) = create_local_store() else {
        return;
    };
    let store = Arc::new(store);
    let Some(key) = create_key(body) else { return };

    let mut bodies: Vec<Vec<u8>> = (0..CONCURRENT_WRITERS)
        .map(|i| {
            let mut b = body.to_vec();
            b.push(i as u8);
            b
        })
        .collect();
    if let Some(first) = bodies.first_mut() {
        *first = body.to_vec();
    }

    let results: Arc<std::sync::Mutex<Vec<Result<PutOutcome, LocalObjectStoreError>>>> =
        Arc::default();
    let store_writer = store.clone();
    let key_writer = key.clone();
    let results_writer = results.clone();
    spawn_concurrent_writers(CONCURRENT_WRITERS, move |i| {
        if let Some(chosen) = bodies.get(i) {
            let h = ShardlineHash::from_bytes(*blake3::hash(chosen).as_bytes());
            let integ = ObjectIntegrity::new(h, chosen.len() as u64);
            if let Ok(result) =
                store_writer.put_if_absent(&key_writer, ObjectBody::from_slice(chosen), &integ)
                && let Ok(mut guard) = results_writer.lock()
            {
                guard.push(Ok(result));
            }
        }
    });

    let inserted = results.lock().map_or(0, |guard| {
        guard
            .iter()
            .filter(|r| matches!(r, Ok(PutOutcome::Inserted)))
            .count()
    });
    assert!(
        inserted <= 1,
        "concurrent put_if_absent for same key with different bodies: \
         expected at most 1 Inserted, got {inserted}"
    );
    if inserted == 0 {
        let all_err = results
            .lock()
            .map_or(true, |guard| guard.iter().all(|r| r.is_err()));
        assert!(
            all_err,
            "conflicting concurrent writes: expected all errors"
        );
    }
}

fn local_concurrent_put_and_read(body: &[u8], integrity: &ObjectIntegrity) {
    let Some((_sandbox, store)) = create_local_store() else {
        return;
    };
    let store = Arc::new(store);
    let Some(key) = create_key(body) else { return };
    let body = body.to_vec();

    let stop = Arc::new(AtomicBool::new(false));
    let reader_store = store.clone();
    let reader_key = key.clone();
    let reader_stop = stop.clone();
    let reader = thread::spawn(move || {
        let mut iterations = 0_u64;
        while !reader_stop.load(Ordering::SeqCst) && iterations < 100 {
            if let Ok(Some(meta)) = reader_store.metadata(&reader_key)
                && let Some(range) = range_up_to(meta.length())
                && let Ok(bytes) = reader_store.read_range(&reader_key, range)
            {
                assert_eq!(bytes.len() as u64, meta.length());
            }
            iterations = iterations.wrapping_add(1);
        }
    });

    store
        .put_if_absent(&key, ObjectBody::from_slice(&body), integrity)
        .ok();
    stop.store(true, Ordering::SeqCst);
    reader.join().ok();
}

fn local_concurrent_contains_and_put(body: &[u8], integrity: &ObjectIntegrity) {
    let Some((_sandbox, store)) = create_local_store() else {
        return;
    };
    let store = Arc::new(store);
    let Some(key) = create_key(body) else { return };
    let body = body.to_vec();

    let stop = Arc::new(AtomicBool::new(false));
    let checker_store = store.clone();
    let checker_key = key.clone();
    let checker_stop = stop.clone();
    let checker = thread::spawn(move || {
        let mut iterations = 0_u64;
        while !checker_stop.load(Ordering::SeqCst) && iterations < 100 {
            checker_store.contains(&checker_key).ok();
            iterations = iterations.wrapping_add(1);
        }
    });

    let outcome = store.put_if_absent(&key, ObjectBody::from_slice(&body), integrity);
    stop.store(true, Ordering::SeqCst);
    checker.join().ok();

    let present = store.contains(&key);
    assert!(present.is_ok(), "contains must succeed after put_if_absent");
    if outcome.is_ok() {
        assert_eq!(
            present.as_ref().ok(),
            Some(&true),
            "object must exist after successful put_if_absent"
        );
    }
}

fn local_concurrent_delete_and_put(body: &[u8], integrity: &ObjectIntegrity) {
    let Some((_sandbox, store)) = create_local_store() else {
        return;
    };
    let store = Arc::new(store);
    let Some(key) = create_key(body) else { return };
    let body = body.to_vec();

    store
        .put_if_absent(&key, ObjectBody::from_slice(&body), integrity)
        .ok();

    let stop = Arc::new(AtomicBool::new(false));
    let deleter_store = store.clone();
    let deleter_key = key.clone();
    let deleter_stop = stop.clone();
    let deleter = thread::spawn(move || {
        let mut iterations = 0_u64;
        while !deleter_stop.load(Ordering::SeqCst) && iterations < 10 {
            deleter_store.delete_if_present(&deleter_key).ok();
            iterations = iterations.wrapping_add(1);
        }
    });

    store
        .put_if_absent(&key, ObjectBody::from_slice(&body), integrity)
        .ok();
    stop.store(true, Ordering::SeqCst);
    deleter.join().ok();
    store.contains(&key).ok();
}

fn async_concurrent_put_same_key_same_body(body: &[u8], _integrity: &ObjectIntegrity) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(key) = create_key(body) else { return };
    let location = ObjectStorePath::from(key.as_str());
    let body = body.to_vec();
    let length = body.len() as u64;

    let results: Arc<std::sync::Mutex<Vec<bool>>> = Arc::default();
    {
        let store = store.clone();
        let location = location.clone();
        let body = body.clone();
        let results = results.clone();
        spawn_concurrent_writers(CONCURRENT_WRITERS, move |_i| {
            if let Some(rt) = build_rt() {
                let inserted = rt.block_on(async {
                    let exists = store
                        .get_opts(&location, GetOptions::new().with_range(Some(0..1)))
                        .await;
                    if exists.is_ok() {
                        return false;
                    }
                    store
                        .put_opts(
                            &location,
                            Bytes::from(body.clone()).into(),
                            PutMode::Create.into(),
                        )
                        .await
                        .is_ok()
                });
                if let Ok(mut guard) = results.lock() {
                    guard.push(inserted);
                }
            }
        });
    }

    let inserted_count = results
        .lock()
        .map_or(0, |guard| guard.iter().filter(|r| **r).count());
    assert!(
        inserted_count <= 1,
        "async concurrent put same key same body: expected at most 1 Inserted, got {inserted_count}"
    );

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            if let Ok(data) = store.get(&location).await {
                let meta = data.meta.clone();
                if let Ok(stored) = data.bytes().await {
                    assert_eq!(stored.as_ref(), body.as_slice());
                    assert_eq!(meta.size, length);
                }
            }
        });
    }
}

fn async_toctou_race_check_then_put(body: &[u8], _integrity: &ObjectIntegrity) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(key) = create_key(body) else { return };
    let location = ObjectStorePath::from(key.as_str());
    let body = body.to_vec();

    let results: Arc<std::sync::Mutex<Vec<Result<(), String>>>> = Arc::default();
    {
        let store = store.clone();
        let location = location.clone();
        let body = body.clone();
        let results = results.clone();
        spawn_concurrent_writers(CONCURRENT_WRITERS, move |_i| {
            if let Some(rt) = build_rt() {
                let result = rt.block_on(async {
                    let head = store.head(&location).await;
                    if head.is_ok() {
                        return Ok(());
                    }
                    store
                        .put_opts(
                            &location,
                            Bytes::from(body.clone()).into(),
                            PutMode::Create.into(),
                        )
                        .await
                        .map(|_| ())
                        .map_err(|e| e.to_string())
                });
                if let Ok(mut guard) = results.lock() {
                    guard.push(result);
                }
            }
        });
    }

    let ok_count = results
        .lock()
        .map_or(0, |guard| guard.iter().filter(|r| r.is_ok()).count());
    assert!(
        ok_count >= 1,
        "TOCTOU race: expected at least 1 successful write"
    );
    assert!(
        ok_count <= CONCURRENT_WRITERS,
        "TOCTOU race: at most {CONCURRENT_WRITERS} inserted, got {ok_count}"
    );
}

fn async_concurrent_put_different_bytes(body: &[u8]) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(key) = create_key(body) else { return };
    let location = ObjectStorePath::from(key.as_str());
    let body_owned = body.to_vec();

    let mut bodies: Vec<Vec<u8>> = (0..CONCURRENT_WRITERS)
        .map(|i| {
            let mut b = body_owned.clone();
            b.push(i as u8);
            b
        })
        .collect();
    bodies[0] = body_owned.clone();

    if let Some(rt) = build_rt() {
        let first_body = bodies
            .first()
            .map_or_else(|| body_owned.clone(), Clone::clone);
        rt.block_on(async {
            let _discard = store
                .put_opts(
                    &location,
                    Bytes::from(first_body).into(),
                    PutMode::Create.into(),
                )
                .await;
        });
    }

    let results: Arc<std::sync::Mutex<Vec<bool>>> = Arc::default();
    let bodies_for_writers = bodies.clone();
    {
        let store = store.clone();
        let location = location.clone();
        let results = results.clone();
        spawn_concurrent_writers(CONCURRENT_WRITERS, move |i| {
            if let Some(rt) = build_rt() {
                let chosen = bodies_for_writers
                    .get(i)
                    .map_or_else(|| body_owned.clone(), Clone::clone);
                let inserted = rt.block_on(async {
                    store
                        .put_opts(
                            &location,
                            Bytes::from(chosen).into(),
                            PutMode::Create.into(),
                        )
                        .await
                        .is_ok()
                });
                if let Ok(mut guard) = results.lock() {
                    guard.push(inserted);
                }
            }
        });
    }

    let inserted_count = results
        .lock()
        .map_or(0, |guard| guard.iter().filter(|r| **r).count());
    assert!(
        inserted_count <= 1,
        "async different bytes: expected at most 1 Inserted, got {inserted_count}"
    );

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            if let Ok(data) = store.get(&location).await
                && let Ok(stored) = data.bytes().await
            {
                let matches = bodies.iter().any(|b| stored.as_ref() == b.as_slice());
                assert!(matches, "stored bytes don't match any written body");
            }
        });
    }

    let inserted_count = results
        .lock()
        .map_or(0, |guard| guard.iter().filter(|r| **r).count());
    assert!(
        inserted_count <= 1,
        "async different bytes: expected at most 1 Inserted, got {inserted_count}"
    );

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            if let Ok(data) = store.get(&location).await
                && let Ok(stored) = data.bytes().await
            {
                let matches = bodies.iter().any(|b| stored.as_ref() == b.as_slice());
                assert!(matches, "stored bytes don't match any written body");
            }
        });
    }
}

fn async_concurrent_delete_and_put(body: &[u8], _integrity: &ObjectIntegrity) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(key) = create_key(body) else { return };
    let location = ObjectStorePath::from(key.as_str());
    let body = body.to_vec();

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            let _discard = store
                .put_opts(
                    &location,
                    Bytes::from(body.clone()).into(),
                    PutMode::Create.into(),
                )
                .await;
        });
    }

    let stop = Arc::new(AtomicBool::new(false));
    let deleter_store = store.clone();
    let deleter_location = location.clone();
    let deleter_stop = stop.clone();
    let deleter = thread::spawn(move || {
        if let Some(rt) = build_rt() {
            rt.block_on(async {
                let mut iterations = 0_u64;
                while !deleter_stop.load(Ordering::SeqCst) && iterations < 10 {
                    let _discard = deleter_store.delete(&deleter_location).await;
                    iterations = iterations.wrapping_add(1);
                }
            });
        }
    });

    let writer_stop = stop.clone();
    let writer_store = store.clone();
    let writer_location = location.clone();
    let writer = thread::spawn(move || {
        if let Some(rt) = build_rt() {
            rt.block_on(async {
                let mut iterations = 0_u64;
                while !writer_stop.load(Ordering::SeqCst) && iterations < 10 {
                    let _discard = writer_store
                        .put_opts(
                            &writer_location,
                            Bytes::from(body.clone()).into(),
                            PutMode::Create.into(),
                        )
                        .await;
                    iterations = iterations.wrapping_add(1);
                }
            });
        }
    });

    stop.store(true, Ordering::SeqCst);
    let _discard = deleter.join();
    let _discard = writer.join();
}

fn async_list_consistency_during_writes(body: &[u8], _integrity: &ObjectIntegrity) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(base_key) = create_key(body) else {
        return;
    };
    let location = ObjectStorePath::from(base_key.as_str());
    let prefix_str = base_key
        .as_str()
        .split('/')
        .next()
        .map_or_else(|| "aa".to_owned(), str::to_owned);
    let body = body.to_vec();

    let stop = Arc::new(AtomicBool::new(false));
    let writer_stop = stop.clone();
    let writer_store = store.clone();
    let writer_location = location.clone();
    let writer = thread::spawn(move || {
        if let Some(rt) = build_rt() {
            rt.block_on(async {
                let mut iterations = 0_u64;
                while !writer_stop.load(Ordering::SeqCst) && iterations < 20 {
                    let _discard = writer_store
                        .put_opts(
                            &writer_location,
                            Bytes::from(body.clone()).into(),
                            PutMode::Overwrite.into(),
                        )
                        .await;
                    iterations = iterations.wrapping_add(1);
                }
            });
        }
    });

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            for _iteration in 0..20 {
                let mut listed = store.list(Some(&ObjectStorePath::from(prefix_str.clone())));
                while let Some(entry) = listed.try_next().await.unwrap_or(None) {
                    assert!(
                        !entry.location.as_ref().is_empty(),
                        "listed key must not be empty"
                    );
                }
            }
        });
    }

    stop.store(true, Ordering::SeqCst);
    let _discard = writer.join();
}

fn async_concurrent_copy_race(body: &[u8], _integrity: &ObjectIntegrity) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(source_key) = create_key(b"source-seed") else {
        return;
    };
    let Some(dest_key) = create_key(body) else {
        return;
    };
    let source_location = ObjectStorePath::from(source_key.as_str());
    let dest_location = ObjectStorePath::from(dest_key.as_str());
    let body = body.to_vec();

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            let _discard = store
                .put_opts(
                    &source_location,
                    Bytes::from(body.clone()).into(),
                    PutMode::Create.into(),
                )
                .await;
        });
    }

    let results: Arc<std::sync::Mutex<Vec<bool>>> = Arc::default();
    {
        let store = store.clone();
        let source_location = source_location.clone();
        let dest_location = dest_location.clone();
        let results = results.clone();
        spawn_concurrent_writers(CONCURRENT_WRITERS, move |_i| {
            if let Some(rt) = build_rt() {
                let ok = rt.block_on(async {
                    let source_head = store.head(&source_location).await;
                    if source_head.is_err() {
                        return false;
                    }
                    store
                        .copy_opts(
                            &source_location,
                            &dest_location,
                            CopyOptions::new().with_mode(CopyMode::Create),
                        )
                        .await
                        .is_ok()
                });
                if let Ok(mut guard) = results.lock() {
                    guard.push(ok);
                }
            }
        });
    }

    let ok_count = results
        .lock()
        .map_or(0, |guard| guard.iter().filter(|r| **r).count());
    assert!(
        ok_count <= 1,
        "concurrent copy race: expected at most 1 successful copy, got {ok_count}"
    );
}

fn async_toctou_multipart_race(body: &[u8], _integrity: &ObjectIntegrity) {
    let store: Arc<InMemory> = Arc::new(InMemory::new());
    let Some(key) = create_key(body) else { return };
    let location = ObjectStorePath::from(key.as_str());

    let chunk_size = if body.is_empty() { 1 } else { body.len() };
    let chunks: Vec<Vec<u8>> = body.chunks(chunk_size).map(|c| c.to_vec()).collect();

    let results: Arc<std::sync::Mutex<Vec<Result<(), String>>>> = Arc::default();
    {
        let store = store.clone();
        let location = location.clone();
        let chunks = chunks.clone();
        let results = results.clone();
        spawn_concurrent_writers(CONCURRENT_WRITERS, move |_i| {
            if let Some(rt) = build_rt() {
                let result = rt.block_on(async {
                    let exists = store.head(&location).await;
                    if exists.is_ok() {
                        return Ok(());
                    }

                    let tmp_seg = location.as_ref().replace('/', "_");
                    let tmp_location = ObjectStorePath::from(format!("__tmp/{tmp_seg}"));

                    for chunk in &chunks {
                        let write = store
                            .put_opts(
                                &tmp_location,
                                Bytes::from(chunk.clone()).into(),
                                PutMode::Overwrite.into(),
                            )
                            .await;
                        if write.is_err() {
                            let _discard = store.delete(&tmp_location).await;
                            return Err("chunk write failed".to_owned());
                        }
                    }

                    let copy = store
                        .copy_opts(
                            &tmp_location,
                            &location,
                            CopyOptions::new().with_mode(CopyMode::Create),
                        )
                        .await;

                    let _discard = store.delete(&tmp_location).await;

                    match copy {
                        Ok(()) => Ok(()),
                        Err(e) => Err(e.to_string()),
                    }
                });
                if let Ok(mut guard) = results.lock() {
                    guard.push(result);
                }
            }
        });
    }

    let ok_count = results
        .lock()
        .map_or(0, |guard| guard.iter().filter(|r| r.is_ok()).count());
    assert!(
        ok_count >= 1,
        "multipart TOCTOU race: expected at least 1 successful write, got {ok_count}"
    );
    assert!(
        ok_count <= CONCURRENT_WRITERS,
        "multipart TOCTOU race: at most {CONCURRENT_WRITERS} writes, got {ok_count}"
    );

    if let Some(rt) = build_rt() {
        rt.block_on(async {
            if let Ok(data) = store.get(&location).await
                && let Ok(stored) = data.bytes().await
            {
                assert_eq!(
                    stored.as_ref(),
                    body,
                    "multipart TOCTOU race: stored bytes must match original body"
                );
            }
        });
    }
}

