            unreachable!("not used in tests")
        }
    }

    #[test]
    fn mark_optional_existing_object_is_referenced() {
        let store = MockObjectStore::new(&["chunks/abc123"]);
        let key = ObjectKey::parse("chunks/abc123").unwrap();
        let mut referenced = HashSet::new();
        let mut missing = HashSet::new();

        mark_optional_object_reference(&store, &key, &mut referenced, &mut missing).unwrap();

        assert!(
            referenced.contains("chunks/abc123"),
            "existing object should be in referenced set"
        );
        assert!(
            missing.is_empty(),
            "existing object should not be in missing set"
        );
    }

    #[test]
    fn mark_optional_missing_object_is_marked_missing() {
        let store = MockObjectStore::new(&[]);
        let key = ObjectKey::parse("chunks/xyz789").unwrap();
        let mut referenced = HashSet::new();
        let mut missing = HashSet::new();

        mark_optional_object_reference(&store, &key, &mut referenced, &mut missing).unwrap();

        assert!(
            referenced.is_empty(),
            "missing object should not be in referenced set"
        );
        assert!(
            missing.contains("chunks/xyz789"),
            "missing object should be in missing set"
        );
    }

    #[test]
    fn mark_optional_already_referenced_is_noop() {
        let store = MockObjectStore::new(&["chunks/abc"]);
        let key = ObjectKey::parse("chunks/abc").unwrap();
        let mut referenced = HashSet::new();
        referenced.insert("chunks/abc".to_owned());
        let mut missing = HashSet::new();

        mark_optional_object_reference(&store, &key, &mut referenced, &mut missing).unwrap();

        // Should not error, and the sets should remain unchanged.
        assert_eq!(referenced.len(), 1);
        assert!(missing.is_empty());
    }

    #[test]
    fn mark_optional_already_missing_is_noop() {
        let store = MockObjectStore::new(&[]);
        let key = ObjectKey::parse("chunks/def").unwrap();
        let mut referenced = HashSet::new();
        let mut missing = HashSet::new();
        missing.insert("chunks/def".to_owned());

        mark_optional_object_reference(&store, &key, &mut referenced, &mut missing).unwrap();

        // Should not error, and the sets should remain unchanged.
        assert!(referenced.is_empty());
        assert_eq!(missing.len(), 1);
    }

    #[test]
    fn managed_object_hash_or_object_key_with_chunk_key_returns_hash() {
        let hash = "abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890";
        let key_str = format!("ab/{hash}");
        let key = ObjectKey::parse(key_str.as_str()).unwrap();
        let result = managed_object_hash_or_object_key(&key, &[]);
        assert_eq!(result, hash);
    }

    #[test]
    fn managed_object_hash_or_object_key_with_unknown_key_returns_key_as_is() {
        let key = ObjectKey::parse("unknown/somevalue").unwrap();
        let result = managed_object_hash_or_object_key(&key, &[]);
        assert_eq!(result, "unknown/somevalue");
    }

    // --- GC safety guarantee tests ---

    const TEST_HASH: &str = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";

    #[test]
    fn managed_object_hash_or_object_key_chunk_format_returns_hash() {
        // Chunk keys use the format <2-char-prefix>/<64-char-hash> where the
        // prefix is the first two characters of the hash.
        let prefix = &TEST_HASH[..2];
        let key = ObjectKey::parse(&format!("{prefix}/{TEST_HASH}")).unwrap();
        let result = managed_object_hash_or_object_key(&key, &[ServerFrontend::Xet]);
        assert_eq!(result, TEST_HASH);
    }

    #[test]
    fn managed_object_hash_or_object_key_xorb_format_returns_hash() {
        // Xorb keys follow the format xorbs/default/<prefix>/<hash>.xorb
        let prefix = &TEST_HASH[..2];
        let key = ObjectKey::parse(&format!("xorbs/default/{prefix}/{TEST_HASH}.xorb")).unwrap();
        let result = managed_object_hash_or_object_key(&key, &[ServerFrontend::Xet]);
        assert_eq!(result, TEST_HASH);
    }

    #[test]
    fn managed_object_hash_or_object_key_shard_format_returns_hash() {
        // Shard keys follow the format shards/<prefix>/<hash>.shard
        let prefix = &TEST_HASH[..2];
        let key = ObjectKey::parse(&format!("shards/{prefix}/{TEST_HASH}.shard")).unwrap();
        let result = managed_object_hash_or_object_key(&key, &[ServerFrontend::Xet]);
        assert_eq!(result, TEST_HASH);
    }

    #[test]
    fn managed_object_hash_or_object_key_oci_format_returns_key_as_is() {
        // OCI keys are not a managed format; the key should be returned as-is.
        let key = ObjectKey::parse(&format!("oci/{TEST_HASH}")).unwrap();
        let result = managed_object_hash_or_object_key(&key, &[ServerFrontend::Xet]);
        assert_eq!(result, format!("oci/{TEST_HASH}"));
    }
}

use std::sync::Arc;

use axum::http::{HeaderMap, header::AUTHORIZATION};
use shardline_protocol::TokenScope;
use shardline_server_core::{AuthContext, AuthError, AuthProvider};

use crate::error::HubApiError;

const MAX_BEARER_TOKEN_BYTES: usize = 8192;

/// Bearer-token verifier for Hub API routes.
#[derive(Clone)]
pub struct HubAuth {
    provider: Arc<dyn AuthProvider>,
}

impl HubAuth {
    /// Creates a new `HubAuth` from a boxed [`AuthProvider`].
    #[must_use]
    pub fn new(provider: Box<dyn AuthProvider>) -> Self {
        Self {
            provider: Arc::from(provider),
        }
    }

    /// Creates a new `HubAuth` from an [`Arc<dyn AuthProvider>`].
    #[must_use]
    pub fn from_arc(provider: Arc<dyn AuthProvider>) -> Self {
        Self { provider }
    }

    /// Validates the `Authorization` header and returns verified claims.
    ///
    /// # Errors
    ///
    /// Returns [`HubApiError::Unauthorized`] if the token is missing or invalid,
    /// or [`HubApiError::Forbidden`] if the scope is insufficient.
    pub fn authorize(
        &self,
        headers: &HeaderMap,
        required_scope: TokenScope,
    ) -> Result<AuthContext, HubApiError> {
        let header = headers
            .get(AUTHORIZATION)
            .ok_or(HubApiError::Unauthorized)?;
        let header = header.to_str().map_err(|e| {
            tracing::debug!("invalid authorization header encoding: {e}");
            HubApiError::InvalidToken
        })?;
        let token = parse_bearer_token(header)?;
        let claims = self.provider.verify_token(token)?;
        if !scope_allows(claims.scope(), required_scope) {
            return Err(HubApiError::Forbidden);
        }
        Ok(AuthContext::new(claims))
    }

    /// Returns a reference to the underlying provider.
    #[must_use]
    pub fn provider(&self) -> &dyn AuthProvider {
        self.provider.as_ref()
    }
}

impl std::fmt::Debug for HubAuth {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("HubAuth")
            .field("provider", &"<dyn AuthProvider>")
            .finish()
    }
}

const fn scope_allows(actual_scope: TokenScope, required_scope: TokenScope) -> bool {
    match required_scope {
        TokenScope::Read => actual_scope.allows_read(),
        TokenScope::Write => actual_scope.allows_write(),
    }
}

fn parse_bearer_token(header: &str) -> Result<&str, HubApiError> {
    let Some(token) = header.strip_prefix("Bearer ") else {
        return Err(HubApiError::InvalidToken);
    };
    if token.trim().is_empty() || token.len() > MAX_BEARER_TOKEN_BYTES {
        return Err(HubApiError::InvalidToken);
    }
    if token.bytes().any(|b| b.is_ascii_whitespace()) {
        return Err(HubApiError::InvalidToken);
    }
    Ok(token)
}

impl From<AuthError> for HubApiError {
    fn from(error: AuthError) -> Self {
        match error {
            AuthError::InvalidToken => Self::InvalidToken,
            AuthError::ExpiredToken => Self::InvalidToken,
            AuthError::InsufficientScope => Self::Forbidden,
            AuthError::ProviderError(msg) => Self::SigningKeyError(msg),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::http::HeaderValue;
    use shardline_protocol::TokenClaims;

    // -----------------------------------------------------------------------
    // parse_bearer_token (private – exercised through authorize)
    // -----------------------------------------------------------------------

    fn make_auth_header(value: &str) -> HeaderMap {
        let mut headers = HeaderMap::new();
        headers.insert(AUTHORIZATION, HeaderValue::from_str(value).unwrap());
        headers
    }

    fn make_mock_provider() -> impl AuthProvider {
        struct MockProvider;
        impl AuthProvider for MockProvider {
            fn verify_token(&self, _token: &str) -> Result<TokenClaims, AuthError> {
                // Build a valid claim so we can reach the scope-check logic.
            let repo = shardline_protocol::RepositoryScope::new(
                shardline_protocol::RepositoryProvider::GitHub,
                "owner",
                "repo",
                Some("main"),
            )
            .map_err(|_err| AuthError::InvalidToken)?;
            TokenClaims::new("issuer", "subject", TokenScope::Read, repo, u64::MAX)
                .map_err(|_err| AuthError::InvalidToken)
            }
            fn mint_token(&self, _claims: &TokenClaims) -> Result<String, AuthError> {
                Err(AuthError::ProviderError(
                    "mock provider does not mint tokens".to_owned(),
                ))
            }
        }
        MockProvider
    }

    #[test]
    fn parse_bearer_token_valid() {
        let headers = make_auth_header("Bearer validtoken123");
        let auth = HubAuth::new(Box::new(make_mock_provider()));
        let result = auth.authorize(&headers, TokenScope::Read);
        assert!(result.is_ok());
    }

    #[test]
    fn parse_bearer_token_empty_after_prefix() {
        let headers = make_auth_header("Bearer ");
        let auth = HubAuth::new(Box::new(make_mock_provider()));
        let result = auth.authorize(&headers, TokenScope::Read);
        assert!(matches!(result, Err(HubApiError::InvalidToken)));
    }

    #[test]
    fn parse_bearer_token_contains_whitespace() {
        let headers = make_auth_header("Bearer a b");
        let auth = HubAuth::new(Box::new(make_mock_provider()));
        let result = auth.authorize(&headers, TokenScope::Read);
        assert!(matches!(result, Err(HubApiError::InvalidToken)));
    }

    #[test]
    fn parse_bearer_token_not_bearer() {
        let headers = make_auth_header("Basic dXNlcjpwYXNz");
        let auth = HubAuth::new(Box::new(make_mock_provider()));
        let result = auth.authorize(&headers, TokenScope::Read);
        assert!(matches!(result, Err(HubApiError::InvalidToken)));
    }

    #[test]
    fn parse_bearer_token_too_long() {
        let long_token = "a".repeat(8193);
        let header_value = format!("Bearer {long_token}");
        let headers = make_auth_header(&header_value);
        let auth = HubAuth::new(Box::new(make_mock_provider()));
        let result = auth.authorize(&headers, TokenScope::Read);
        assert!(matches!(result, Err(HubApiError::InvalidToken)));
    }

    #[test]
    fn parse_bearer_token_no_authorization_header() {
        let headers = HeaderMap::new();
        let auth = HubAuth::new(Box::new(make_mock_provider()));
        let result = auth.authorize(&headers, TokenScope::Read);
        assert!(matches!(result, Err(HubApiError::Unauthorized)));
    }

    // -----------------------------------------------------------------------
    // scope_allows
    // -----------------------------------------------------------------------

    #[test]
    fn scope_allows_read_for_read() {
        assert!(scope_allows(TokenScope::Read, TokenScope::Read));
    }

    #[test]
    fn scope_allows_write_for_read() {
        assert!(scope_allows(TokenScope::Write, TokenScope::Read));
    }

    #[test]
    fn scope_allows_read_for_write_fails() {
        assert!(!scope_allows(TokenScope::Read, TokenScope::Write));
    }

    #[test]
    fn scope_allows_write_for_write() {
        assert!(scope_allows(TokenScope::Write, TokenScope::Write));
    }

    // -----------------------------------------------------------------------
    // From<AuthError> for HubApiError
    // -----------------------------------------------------------------------

    #[test]
    fn auth_error_invalid_token_maps_to_invalid_token() {
        let err: HubApiError = AuthError::InvalidToken.into();
        assert!(matches!(err, HubApiError::InvalidToken));
    }

    #[test]
    fn auth_error_expired_token_maps_to_invalid_token() {
        let err: HubApiError = AuthError::ExpiredToken.into();
        assert!(matches!(err, HubApiError::InvalidToken));
    }

    #[test]
    fn auth_error_insufficient_scope_maps_to_forbidden() {
        let err: HubApiError = AuthError::InsufficientScope.into();
        assert!(matches!(err, HubApiError::Forbidden));
    }

    #[test]
    fn auth_error_provider_error_maps_to_signing_key_error() {
        let err: HubApiError = AuthError::ProviderError("boom".into()).into();
        assert!(
            matches!(&err, HubApiError::SigningKeyError(msg) if msg == "boom"),
            "expected SigningKeyError(\"boom\"), got {err:?}"
        );
    }
}

use std::collections::HashMap;

use base64::Engine;
use base64::engine::general_purpose::STANDARD;

use crate::error::HubApiError;

/// Maximum allowed commit file path length.
const MAX_COMMIT_PATH_LEN: usize = 1024;

/// Maximum number of instructions allowed in a single NDJSON commit.
const MAX_COMMIT_INSTRUCTIONS: usize = 100_000;

/// Maximum decoded size (in bytes) for a single inline file in a commit.
/// Files exceeding this limit must use LFS.
const MAX_INLINE_FILE_BYTES: usize = 10 * 1024 * 1024; // 10 MiB

/// Validates a commit file path to prevent path traversal and injection.
///
/// Rejects paths that:
/// - Contain `..` components
/// - Start with `/` (absolute paths)
/// - Contain null bytes
/// - Contain control characters (ASCII 0x00–0x1F, 0x7F)
/// - Exceed the maximum allowed length
fn validate_commit_path(path: &str) -> Result<(), HubApiError> {
    if path.len() > MAX_COMMIT_PATH_LEN {
        return Err(HubApiError::PathValidation(format!(
            "commit path exceeds maximum length of {MAX_COMMIT_PATH_LEN}"
        )));
    }

    if path.starts_with('/') {
        return Err(HubApiError::PathValidation(
            "commit path must not be absolute".to_owned(),
        ));
    }

    if path.contains('\0') {
        return Err(HubApiError::PathValidation(
            "commit path contains null byte".to_owned(),
        ));
    }

    if path.bytes().any(|b| b < 0x20 || b == 0x7f) {
        return Err(HubApiError::PathValidation(
            "commit path contains control characters".to_owned(),
        ));
    }

    // Check for path traversal via `..` components.
    for component in path.split('/') {
        if component == ".." {
            return Err(HubApiError::PathValidation(
                "commit path must not contain '..' components".to_owned(),
            ));
        }
    }

    Ok(())
}

/// A parsed commit instruction.
#[derive(Debug, Clone)]
pub enum CommitInstruction {
    /// Inline file content.
    InlineFile {
        /// Relative path.
        path: String,
        /// Decoded content bytes.
        content: Vec<u8>,
    },
    /// LFS pointer reference.
    LfsPointer {
        /// Relative path.
        path: String,
        /// LFS OID (SHA-256).
        oid: String,
        /// File size.
        size: u64,
    },
    /// File deletion.
    Delete {
        /// Relative path.
        path: String,
    },
}

/// Parsed commit request.
#[derive(Debug, Clone)]
pub struct ParsedCommit {
    /// Commit message.
    pub message: String,
    /// Parent revision SHA (if any).
    pub parent_commit: Option<String>,
    /// Parsed instructions.
    pub instructions: Vec<CommitInstruction>,
}

/// Parses a streaming NDJSON commit body.
///
/// Expected lines:
/// - `{"header":{"message":"...","parentCommit":"..."}}` (or `"summary"` instead of `"message"`)
/// - `{"file":{"path":"...","content":"<base64>"}}`
/// - `{"lfsFile":{"path":"...","oid":"...","size":123}}`
/// - `{"deletedEntry":{"path":"..."}}`
///
/// # Errors
///
/// Returns [`HubApiError`] on malformed input.
pub fn parse_ndjson_commit(body: &str) -> Result<ParsedCommit, HubApiError> {
    let mut message = String::new();
    let mut parent_commit = None;
    let mut instructions = Vec::new();

    for (line_idx, line) in body.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let parsed: HashMap<String, serde_json::Value> =
            serde_json::from_str(trimmed).map_err(HubApiError::Json)?;

        if let Some(header) = parsed.get("header") {
            // Accept both "message" (internal) and "summary" (HuggingFace Hub spec).
            if let Some(msg) = header
                .get("message")
                .or_else(|| header.get("summary"))
                .and_then(|v| v.as_str())
            {
                message = msg.to_owned();
            }
            if let Some(parent) = header.get("parentCommit").and_then(|v| v.as_str())
                && !parent.is_empty()
            {
                parent_commit = Some(parent.to_owned());
            }
            continue;
        }

        if instructions.len() >= MAX_COMMIT_INSTRUCTIONS {
            return Err(HubApiError::PathValidation(format!(
                "commit contains too many instructions (max {MAX_COMMIT_INSTRUCTIONS})"
            )));
        }

        if let Some(file) = parsed.get("file") {
            let path = file.get("path").and_then(|v| v.as_str()).ok_or_else(|| {
                HubApiError::PathValidation(format!("line {line_idx}: missing file path"))
            })?;
            validate_commit_path(path)?;
            let content_b64 = file
                .get("content")
                .and_then(|v| v.as_str())
                .ok_or_else(|| {
                    HubApiError::PathValidation(format!("line {line_idx}: missing file content"))
                })?;
            let content = STANDARD.decode(content_b64).map_err(|e| {
                HubApiError::PathValidation(format!("line {line_idx}: invalid base64: {e}"))
            })?;
            if content.len() > MAX_INLINE_FILE_BYTES {
                return Err(HubApiError::PathValidation(format!(
                    "line {line_idx}: inline file size {} exceeds maximum of {MAX_INLINE_FILE_BYTES} bytes; use LFS for large files",
                    content.len()
                )));
            }
            instructions.push(CommitInstruction::InlineFile {
                path: path.to_owned(),
                content,
            });
            continue;
        }

        if let Some(lfs_file) = parsed.get("lfsFile") {
            let path = lfs_file
                .get("path")
                .and_then(|v| v.as_str())
                .ok_or_else(|| {
                    HubApiError::PathValidation(format!("line {line_idx}: missing lfsFile path"))
                })?;
            validate_commit_path(path)?;
            let oid = lfs_file
                .get("oid")
                .and_then(|v| v.as_str())
                .ok_or_else(|| {
                    HubApiError::PathValidation(format!("line {line_idx}: missing lfsFile oid"))
                })?;
            let size = lfs_file
                .get("size")
                .and_then(|v| v.as_u64())
                .ok_or_else(|| {
                    HubApiError::PathValidation(format!("line {line_idx}: missing lfsFile size"))
                })?;
            instructions.push(CommitInstruction::LfsPointer {
                path: path.to_owned(),
                oid: oid.to_owned(),
                size,
            });
            continue;
        }

        if let Some(deleted) = parsed.get("deletedEntry") {
            let path = deleted
                .get("path")
                .and_then(|v| v.as_str())
                .ok_or_else(|| {
                    HubApiError::PathValidation(format!(
                        "line {line_idx}: missing deletedEntry path"
                    ))
                })?;
            validate_commit_path(path)?;
            instructions.push(CommitInstruction::Delete {
                path: path.to_owned(),
            });
            continue;
        }

        return Err(HubApiError::PathValidation(format!(
            "line {line_idx}: unknown commit instruction type"
        )));
    }

    if message.is_empty() {
        return Err(HubApiError::PathValidation(
            "commit header with message (or summary) is required".to_owned(),
        ));
    }

    Ok(ParsedCommit {
        message,
        parent_commit,
        instructions,
    })
}

/// Validates an LFS OID format (64 lowercase hex characters for SHA-256).
///
/// # Errors
///
/// Returns [`HubApiError::PathValidation`] if the OID is malformed.
pub fn validate_lfs_oid(oid: &str) -> Result<(), HubApiError> {
    if oid.len() != 64
        || !oid
            .bytes()
            .all(|b| b.is_ascii_digit() || matches!(b, b'a'..=b'f'))
    {
        return Err(HubApiError::PathValidation(format!(
            "invalid LFS OID: {oid}"
        )));
    }
    Ok(())
}

