    // --- repo_delete endpoint logic tests ---
    // These test the store operations that the repo_delete handler relies on,
    // using BoxedHubStore with the same flow the handler follows.

    fn make_delete_test_store() -> (tempfile::TempDir, BoxedHubStore) {
        let ts = tempfile::tempdir().expect("tempdir");
        let root = ts.path();

        // Create hub tables using the public API
        shardline_index::hub::ensure_hub_tables(root).expect("ensure hub tables");

        let store = shardline_index::LocalIndexStore::open(root.to_path_buf());
        let boxed = BoxedHubStore::from_store(store);
        (ts, boxed)
    }

    #[test]
    fn repo_delete_cleans_up_revisions() {
        let (_ts, store) = make_delete_test_store();

        use shardline_index::hub::{HubFileEntry, HubRepoType};

        store
            .create_repo(HubRepoType::Model, "org/model", false)
            .unwrap();
        let initial_sha = "4b825dc642cb6eb9a060e54bf899d69f8f5ce8e3";

        // Add a commit
        store
            .create_revision(
                "org/model",
                Some(initial_sha),
                "sha1",
                "main",
                "first commit",
            )
            .unwrap();

        // Store files for the commit
        let files = vec![HubFileEntry {
            path: "README.md".into(),
            size: 100,
            sha: "sha_readme".into(),
            is_lfs: false,
            inline_content: None,
        }];
        store.store_files("sha1", &files).unwrap();

        // Verify data exists
        assert_eq!(store.list_revisions("org/model").unwrap().len(), 2);
        assert_eq!(store.get_files("sha1").unwrap().len(), 1);

        // Delete — mirrors what repo_delete handler does
        store.delete_repo("org/model").unwrap();

        // Verify everything is gone
        assert!(store.get_repo("org/model").unwrap().is_none());
        assert!(store.list_revisions("org/model").unwrap().is_empty());
        assert!(store.get_files("sha1").unwrap().is_empty());
    }

    #[test]
    fn repo_delete_cleans_up_webhooks() {
        let (_ts, store) = make_delete_test_store();

        use shardline_index::hub::HubRepoType;

        store
            .create_repo(HubRepoType::Model, "org/model", false)
            .unwrap();

        // Create webhook
        store
            .create_webhook(
                "org/model",
                "https://example.com/hook",
                &["push".into()],
                None,
            )
            .unwrap();

        assert_eq!(store.list_webhooks("org/model").unwrap().len(), 1);

        // Delete
        store.delete_repo("org/model").unwrap();

        // Verify webhook is gone
        assert!(store.list_webhooks("org/model").unwrap().is_empty());
    }

    #[test]
    fn repo_delete_idempotent() {
        let (_ts, store) = make_delete_test_store();

        use shardline_index::hub::HubRepoType;

        store
            .create_repo(HubRepoType::Model, "org/model", false)
            .unwrap();

        // First delete succeeds
        store.delete_repo("org/model").unwrap();
        assert!(store.get_repo("org/model").unwrap().is_none());

        // Second delete is also fine (no-op, no rows affected)
        store.delete_repo("org/model").unwrap();
        assert!(store.get_repo("org/model").unwrap().is_none());
    }
}

use std::sync::{Mutex, Once, OnceLock};

use shardline_hub_api::routes::HubState;
use shardline_index::LocalIndexStore;
use shardline_index::hub::BoxedHubStore;
use tempfile::TempDir;

pub(crate) static INIT: Once = Once::new();
pub(crate) static TEMP_DIR: OnceLock<Mutex<Option<TempDir>>> = OnceLock::new();
pub(crate) static STATE: OnceLock<HubState> = OnceLock::new();

pub(crate) const HUB_SCHEMA: &str = "CREATE TABLE IF NOT EXISTS shardline_hub_repos (
                repo_id TEXT PRIMARY KEY,
                repo_type TEXT NOT NULL CHECK (repo_type IN ('model', 'dataset', 'space')),
                private INTEGER NOT NULL DEFAULT 0 CHECK (private IN (0, 1)),
                default_branch TEXT NOT NULL,
                created_at_unix_seconds INTEGER NOT NULL CHECK (created_at_unix_seconds >= 0),
                updated_at_unix_seconds INTEGER NOT NULL CHECK (updated_at_unix_seconds >= 0)
            );
            CREATE TABLE IF NOT EXISTS shardline_hub_revisions (
                repo_id TEXT NOT NULL,
                ref_name TEXT NOT NULL,
                sha TEXT NOT NULL,
                parent_sha TEXT,
                message TEXT,
                created_at_unix_seconds INTEGER NOT NULL CHECK (created_at_unix_seconds >= 0),
                PRIMARY KEY (repo_id, sha),
                FOREIGN KEY (repo_id) REFERENCES shardline_hub_repos(repo_id) ON DELETE CASCADE
            );
            CREATE INDEX IF NOT EXISTS shardline_hub_revisions_repo_ref_idx
                ON shardline_hub_revisions (repo_id, ref_name);
            CREATE TABLE IF NOT EXISTS shardline_hub_file_entries (
                commit_sha TEXT NOT NULL,
                path TEXT NOT NULL,
                size INTEGER NOT NULL CHECK (size >= 0),
                sha TEXT NOT NULL,
                is_lfs INTEGER NOT NULL DEFAULT 0 CHECK (is_lfs IN (0, 1)),
                inline_content BLOB,
                PRIMARY KEY (commit_sha, path)
            );
            CREATE TABLE IF NOT EXISTS shardline_hub_lfs_objects (
                oid TEXT PRIMARY KEY,
                data BLOB NOT NULL,
                size INTEGER NOT NULL CHECK (size >= 0),
                created_at_unix_seconds INTEGER NOT NULL CHECK (created_at_unix_seconds >= 0)
            );
            CREATE TABLE IF NOT EXISTS shardline_hub_webhooks (
                id TEXT PRIMARY KEY,
                repo_id TEXT NOT NULL,
                url TEXT NOT NULL,
                events TEXT NOT NULL DEFAULT 'push',
                secret TEXT,
                active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
                created_at_unix_seconds INTEGER NOT NULL CHECK (created_at_unix_seconds >= 0),
                FOREIGN KEY (repo_id) REFERENCES shardline_hub_repos(repo_id) ON DELETE CASCADE
            );
            CREATE INDEX IF NOT EXISTS shardline_hub_webhooks_repo_idx ON shardline_hub_webhooks (repo_id);";

pub(crate) fn setup() {
    INIT.call_once(|| {
        let tmp = TempDir::new().expect("tempdir");
        let root = tmp.path().to_path_buf();
        let db_path = root.join("metadata.sqlite3");
        let conn = rusqlite::Connection::open(&db_path).expect("open sqlite");
        conn.execute_batch(HUB_SCHEMA).expect("execute schema");
        drop(conn);

        let store = LocalIndexStore::open(root);
        let boxed = BoxedHubStore::from_store(store);
        let state = HubState {
            store: boxed,
            auth: None,
            http_client: None,
        };
        let _ = STATE.set(state);

        let dir_lock = TEMP_DIR.get_or_init(|| Mutex::new(None));
        *dir_lock.lock().unwrap() = Some(tmp);
    });
}

pub(crate) fn state() -> &'static HubState {
    STATE.get().expect("setup() must be called first")
}

pub(crate) fn app() -> axum::Router {
    shardline_hub_api::hub_routes(state().clone())
}

