const fn next_state_machine_value(state: u64) -> u64 {
    state
        .wrapping_mul(6_364_136_223_846_793_005)
        .wrapping_add(1_442_695_040_888_963_407)
}

fn state_machine_index(state: u64, shift: u32, len: usize) -> Result<usize, Box<dyn Error>> {
    let len_u64 = u64::try_from(len)?;
    if len_u64 == 0 {
        return Err(LocalSqliteInvariantError::new("state-machine fixture list was empty").into());
    }
    let shifted = state.checked_shr(shift).unwrap_or(0);
    let bounded = shifted
        .checked_rem(len_u64)
        .ok_or_else(|| LocalSqliteInvariantError::new("state-machine modulus overflowed"))?;
    Ok(usize::try_from(bounded)?)
}

fn state_machine_item<'values, T>(
    values: &'values [T],
    index: usize,
    what: &str,
) -> Result<&'values T, Box<dyn Error>> {
    values.get(index).ok_or_else(|| {
        LocalSqliteInvariantError::new(format!("missing state-machine {what} at index {index}"))
            .into()
    })
}

async fn assert_local_sqlite_matches_memory_state(
    local_record_store: &LocalRecordStore,
    memory_record_store: &MemoryRecordStore,
    local_index_store: &LocalIndexStore,
    memory_index_store: &MemoryIndexStore,
    fixtures: &StateMachineFixtures,
) -> Result<(), Box<dyn Error>> {
    if canonical_record_entries(local_record_store, true).await?
        != canonical_record_entries(memory_record_store, true).await?
    {
        return Err(
            LocalSqliteInvariantError::new("latest-record state diverged from memory").into(),
        );
    }
    if canonical_record_entries(local_record_store, false).await?
        != canonical_record_entries(memory_record_store, false).await?
    {
        return Err(
            LocalSqliteInvariantError::new("version-record state diverged from memory").into(),
        );
    }

    for record in &fixtures.records {
        if RecordTraversal::read_latest_record_bytes(local_record_store, record).await?
            != RecordTraversal::read_latest_record_bytes(memory_record_store, record).await?
        {
            return Err(LocalSqliteInvariantError::new(
                "latest-record lookup diverged from memory",
            )
            .into());
        }
    }

    let reconstruction_file_ids = fixtures
        .reconstructions
        .iter()
        .map(|(file_id, _reconstruction)| *file_id)
        .collect::<Vec<_>>();
    for file_id in reconstruction_file_ids {
        if ReconstructionStore::reconstruction(local_index_store, &file_id)?
            != ReconstructionStore::reconstruction(memory_index_store, &file_id)?
        {
            return Err(LocalSqliteInvariantError::new(
                "reconstruction state diverged from memory",
            )
            .into());
        }
    }

    for xorb_id in &fixtures.xorb_ids {
        if ReconstructionStore::contains_xorb(local_index_store, xorb_id)?
            != ReconstructionStore::contains_xorb(memory_index_store, xorb_id)?
        {
            return Err(
                LocalSqliteInvariantError::new("xorb marker state diverged from memory").into(),
            );
        }
    }

    if canonical_dedupe_mappings(DedupeStore::list_dedupe_shard_mappings(local_index_store)?)
        != canonical_dedupe_mappings(DedupeStore::list_dedupe_shard_mappings(memory_index_store)?)
    {
        return Err(
            LocalSqliteInvariantError::new("dedupe mapping state diverged from memory").into(),
        );
    }

    if canonical_quarantine_candidates(LifecycleStore::list_quarantine_candidates(
        local_index_store,
    )?) != canonical_quarantine_candidates(LifecycleStore::list_quarantine_candidates(
        memory_index_store,
    )?) {
        return Err(LocalSqliteInvariantError::new(
            "quarantine candidate state diverged from memory",
        )
        .into());
    }

    if canonical_retention_holds(LifecycleStore::list_retention_holds(local_index_store)?)
        != canonical_retention_holds(LifecycleStore::list_retention_holds(memory_index_store)?)
    {
        return Err(
            LocalSqliteInvariantError::new("retention hold state diverged from memory").into(),
        );
    }

    if canonical_webhook_deliveries(LifecycleStore::list_webhook_deliveries(local_index_store)?)
        != canonical_webhook_deliveries(LifecycleStore::list_webhook_deliveries(
            memory_index_store,
        )?)
    {
        return Err(
            LocalSqliteInvariantError::new("webhook delivery state diverged from memory").into(),
        );
    }

    if canonical_provider_states(LifecycleStore::list_provider_repository_states(
        local_index_store,
    )?) != canonical_provider_states(LifecycleStore::list_provider_repository_states(
        memory_index_store,
    )?) {
        return Err(LocalSqliteInvariantError::new(
            "provider repository state diverged from memory",
        )
        .into());
    }

    let mut expected_provider_keys = fixtures
        .provider_states
        .iter()
        .map(|state| {
            (
                state.provider(),
                state.owner().to_owned(),
                state.repo().to_owned(),
            )
        })
        .collect::<Vec<_>>();
    expected_provider_keys.sort_by(|left, right| {
        (left.0.as_str(), left.1.as_str(), left.2.as_str()).cmp(&(
            right.0.as_str(),
            right.1.as_str(),
            right.2.as_str(),
        ))
    });
    expected_provider_keys.dedup();
    for (provider, owner, repo) in expected_provider_keys {
        if LifecycleStore::provider_repository_state(local_index_store, provider, &owner, &repo)?
            != LifecycleStore::provider_repository_state(
                memory_index_store,
                provider,
                &owner,
                &repo,
            )?
        {
            return Err(LocalSqliteInvariantError::new(
                "provider repository lookup diverged from memory",
            )
            .into());
        }
    }

    Ok(())
}

async fn canonical_record_entries<Store>(
    store: &Store,
    latest: bool,
) -> Result<Vec<CanonicalRecord>, Box<dyn Error>>
where
    Store: RecordStore,
    Store::Error: Error + Send + Sync + 'static,
{
    let locators = if latest {
        RecordTraversal::list_latest_record_locators(store).await?
    } else {
        RecordTraversal::list_version_record_locators(store).await?
    };
    let mut entries = Vec::with_capacity(locators.len());
    for locator in locators {
        let bytes = RecordTraversal::read_record_bytes(store, &locator).await?;
        let record = from_slice::<FileRecord>(&bytes)?;
        entries.push(canonical_file_record(&record));
    }
    entries.sort();
    Ok(entries)
}

fn canonical_file_record(record: &FileRecord) -> CanonicalRecord {
    let scope = record.repository_scope.as_ref().map(|repository_scope| {
        format!(
            "{}:{}/{}/{}",
            repository_scope.provider().as_str(),
            repository_scope.owner(),
            repository_scope.name(),
            repository_scope.revision().unwrap_or("")
        )
    });
    let chunks = record
        .chunks
        .iter()
        .map(|chunk| {
            (
                chunk.hash.clone(),
                chunk.offset,
                chunk.length,
                chunk.range_start,
                chunk.range_end,
                chunk.packed_start,
                chunk.packed_end,
            )
        })
        .collect::<Vec<_>>();
    (
        scope,
        record.file_id.clone(),
        record.content_hash.clone(),
        record.total_bytes,
        record.chunk_size,
        chunks,
    )
}

fn canonical_dedupe_mappings(mappings: Vec<DedupeShardMapping>) -> Vec<(String, String)> {
    let mut canonical = mappings
        .into_iter()
        .map(|mapping| {
            (
                xet_hash_hex_string(mapping.chunk_hash()),
                mapping.shard_object_key().as_str().to_owned(),
            )
        })
        .collect::<Vec<_>>();
    canonical.sort();
    canonical
}

fn canonical_quarantine_candidates(
    candidates: Vec<QuarantineCandidate>,
