        assert!(range.is_ok());
        let Ok(range) = range else {
            return;
        };
        let term = ReconstructionTerm::new(xorb_id, range, 512);

        assert_eq!(term.object_id(), StoredObjectId::new(hash));
        assert_eq!(term.xorb_id(), xorb_id);
        assert_eq!(term.chunk_range(), range);
