#[tokio::test]
async fn append_upload_bytes_extends_session() {
    let root = temp_root();
    let session_id = create_test_session(root.path(), false).await.unwrap();
    append_upload_bytes(root.path(), &session_id, b"hello")
        .await
        .unwrap();
