const HASH_HEX: &str = "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f";

fn protocol_benchmarks(criterion: &mut Criterion) {
    let hash = must(
        ShardlineHash::parse_hex(HASH_HEX),
        "benchmark hash fixture should parse",
    );
    let repository = must(
        RepositoryScope::new(
            RepositoryProvider::GitHub,
            "team",
            "assets",
            Some("refs/heads/main"),
        ),
        "benchmark repository scope fixture should be valid",
    );
    let claims = must(
        TokenClaims::new(
            "bench-issuer",
            "bench-subject",
            TokenScope::Write,
            repository,
            u64::MAX,
        ),
        "benchmark token claims fixture should be valid",
    );
    let signer = must(
        TokenSigner::new(b"benchmark-signing-key-32-bytes!!"),
        "benchmark token signer fixture should be valid",
    );
    let token = must(
        signer.sign(&claims),
        "benchmark token signing fixture should be valid",
    );

    let mut group = criterion.benchmark_group("shardline_protocol");
    group.bench_function("hash_parse_hex", |bench| {
        bench.iter(|| {
            must(
                ShardlineHash::parse_hex(black_box(HASH_HEX)),
                "hash parse failed",
            )
        });
    });
    group.bench_function("hash_hex_string", |bench| {
        bench.iter(|| black_box(hash).hex_string());
    });
    group.bench_function("byte_range_new_and_len", |bench| {
        bench.iter(|| {
            let range = must(
                ByteRange::new(black_box(4096), black_box(8191)),
                "range failed",
            );
            black_box(range.len())
        });
    });
    group.bench_function("chunk_range_new", |bench| {
        bench.iter(|| {
            must(
                ChunkRange::new(black_box(32), black_box(96)),
                "chunk range failed",
            )
        });
    });
    group.bench_function("token_sign", |bench| {
        bench.iter(|| must(signer.sign(black_box(&claims)), "token sign failed"));
    });
    group.bench_function("token_verify_at", |bench| {
        bench.iter(|| {
            must(
                signer.verify_at(black_box(&token), black_box(1)),
                "token verify failed",
            )
        });
    });
    group.finish();
}

fn must<T, E: Display>(result: Result<T, E>, context: &str) -> T {
    match result {
        Ok(value) => value,
        Err(error) => {
            eprintln!("{context}: {error}");
            abort();
        }
    }
}

criterion_group!(benches, protocol_benchmarks);
criterion_main!(benches);

use serde::{Deserialize, Serialize};
use thiserror::Error;

const HASH_BYTE_LENGTH: usize = 32;
const HASH_HEX_LENGTH: usize = 64;

/// A 32-byte protocol hash.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct ShardlineHash {
    bytes: [u8; HASH_BYTE_LENGTH],
}

impl ShardlineHash {
    /// Creates a hash from raw bytes.
    #[must_use]
    pub const fn from_bytes(bytes: [u8; HASH_BYTE_LENGTH]) -> Self {
        Self { bytes }
    }

    /// Returns the raw hash bytes.
    #[must_use]
    pub const fn as_bytes(&self) -> &[u8; HASH_BYTE_LENGTH] {
        &self.bytes
    }

    /// Parses a hash from canonical lowercase hexadecimal text.
    ///
    /// # Errors
    ///
    /// Returns [`HashParseError`] when the string has the wrong length, contains
    /// non-lowercase hexadecimal characters, or cannot be decoded into 32 bytes.
    pub fn parse_hex(value: &str) -> Result<Self, HashParseError> {
        if value.len() != HASH_HEX_LENGTH {
            return Err(HashParseError::InvalidLength);
        }

        if !value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
        {
            return Err(HashParseError::InvalidCharacter);
        }

        let decoded = hex::decode(value).map_err(|_error| HashParseError::InvalidCharacter)?;
        let bytes = <[u8; HASH_BYTE_LENGTH]>::try_from(decoded)
            .map_err(|_error| HashParseError::InvalidLength)?;

        Ok(Self { bytes })
    }

    /// Returns canonical lowercase hexadecimal text.
    #[must_use]
    pub fn hex_string(&self) -> String {
        let mut encoded = Vec::with_capacity(HASH_HEX_LENGTH);
        for byte in self.bytes {
            append_lower_hex_byte(&mut encoded, byte);
        }

        String::from_utf8(encoded).unwrap_or_default()
    }
}

fn append_lower_hex_byte(output: &mut Vec<u8>, byte: u8) {
    output.push(lower_hex_digit(byte >> 4));
    output.push(lower_hex_digit(byte & 0x0f));
}

const fn lower_hex_digit(nibble: u8) -> u8 {
    match nibble {
        0 => b'0',
        1 => b'1',
        2 => b'2',
        3 => b'3',
        4 => b'4',
        5 => b'5',
        6 => b'6',
        7 => b'7',
        8 => b'8',
        9 => b'9',
        10 => b'a',
        11 => b'b',
        12 => b'c',
        13 => b'd',
        14 => b'e',
        _ => b'f',
    }
}

/// Hash parsing failure.
#[derive(Debug, Clone, Copy, Error, PartialEq, Eq)]
pub enum HashParseError {
    /// The hash string did not contain exactly 64 hexadecimal characters.
    #[error("hash must contain exactly 64 lowercase hexadecimal characters")]
    InvalidLength,
    /// The hash string contained a character outside lowercase hexadecimal.
    #[error("hash must use lowercase hexadecimal characters only")]
    InvalidCharacter,
}

