/// Summary of one handled provider webhook.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProviderWebhookOutcome {
    /// Affected provider family.
    pub provider: ProviderKind,
    /// Affected repository owner or namespace.
    pub owner: String,
    /// Affected repository name.
    pub repo: String,
    /// Provider delivery identifier.
    pub delivery_id: String,
    /// Normalized webhook event kind.
    pub event_kind: ProviderWebhookOutcomeKind,
    /// Number of file-version records scanned for the repository.
    pub affected_file_versions: u64,
    /// Number of distinct chunk objects referenced by affected file versions.
    pub affected_chunks: u64,
    /// Number of retention holds inserted or refreshed by the event.
    pub applied_holds: u64,
    /// Retention applied to newly created holds, if any.
    pub retention_seconds: Option<u64>,
}

/// Publicly reportable webhook outcome kind.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProviderWebhookOutcomeKind {
    /// Repository deletion created durable retention holds.
    RepositoryDeleted,
    /// Repository rename migrated durable metadata into the new repository scope.
    RepositoryRenamed {
        /// New repository owner or namespace.
        new_owner: String,
        /// New repository name.
        new_repo: String,
    },
    /// Repository access changed without durable state mutation.
    AccessChanged,
    /// A revision moved without durable state mutation.
    RevisionPushed {
        /// Updated revision reference.
        revision: String,
    },
}

/// Default retention window for new local quarantine candidates.
pub use shardline_server_core::DEFAULT_LOCAL_GC_RETENTION_SECONDS;

/// Provider webhook event processing failure.
#[derive(Debug, Error)]
pub enum ProviderEventsError {
    /// Arithmetic overflowed a checked bound.
    #[error("arithmetic overflow")]
    Overflow,
    /// A content hash was malformed.
    #[error("content hash must be 64 hexadecimal characters")]
    InvalidContentHash,
    /// The provider webhook payload was invalid.
    #[error("provider webhook payload was invalid")]
    InvalidProviderWebhookPayload,
    /// Repository rename encountered conflicting target-scope metadata.
    #[error("repository rename target already contains conflicting metadata")]
    ConflictingRenameTargetRecord,
    /// JSON serialization or deserialization failed.
    #[error("json operation failed")]
    Json(#[from] JsonError),
    /// Numeric conversion exceeded supported bounds.
    #[error("numeric conversion exceeded supported bounds")]
    NumericConversion(#[from] TryFromIntError),
    /// Retention hold input was invalid.
    #[error("retention hold input was invalid")]
    RetentionHold(#[from] RetentionHoldError),
    /// Xet adapter operation failed.
    #[error("xet adapter operation failed")]
    XetAdapter(#[from] XetAdapterError),
    /// Index adapter access failed.
    #[error("index adapter operation failed")]
    IndexStore(#[from] LocalIndexStoreError),
    /// In-memory index adapter access failed.
    #[error("memory index adapter operation failed")]
    MemoryIndexStore(#[from] MemoryIndexStoreError),
    /// In-memory record adapter access failed.
    #[error("memory record adapter operation failed")]
    MemoryRecordStore(#[from] MemoryRecordStoreError),
    /// Postgres metadata adapter access failed.
    #[error("postgres metadata adapter operation failed")]
    PostgresMetadata(#[from] PostgresMetadataStoreError),
    /// Webhook delivery metadata was invalid.
    #[error("webhook delivery metadata was invalid")]
    WebhookDelivery(#[from] WebhookDeliveryError),
    /// Object-store backend operation failed.
    #[error("object storage operation failed")]
    ObjectStore(#[from] ServerObjectStoreError),
    /// Stored file record parsing failed.
    #[error("stored file record parsing failed")]
    ParseStoredFileRecord(#[from] ParseStoredFileRecordError),
}

fn duplicate_webhook_outcome(event: &RepositoryWebhookEvent) -> ProviderWebhookOutcome {
    ProviderWebhookOutcome {
        provider: event.repository().provider(),
        owner: event.repository().owner().to_owned(),
        repo: event.repository().name().to_owned(),
        delivery_id: event.delivery_id().as_str().to_owned(),
        event_kind: outcome::duplicate_webhook_event_kind(event.kind()),
        affected_file_versions: 0,
        affected_chunks: 0,
        applied_holds: 0,
        retention_seconds: None,
    }
}

/// Applies a normalized provider webhook to Shardline lifecycle state.
///
/// # Errors
///
/// Returns [`ProviderEventsError`] when record or index storage cannot be read
/// or updated.
pub async fn apply_provider_webhook_with_stores<RecordAdapter, IndexAdapter>(
    record_store: &RecordAdapter,
    index_store: &IndexAdapter,
    object_store: &shardline_server_core::ServerObjectStore,
    event: &RepositoryWebhookEvent,
) -> Result<ProviderWebhookOutcome, ProviderEventsError>
where
    RecordAdapter: RecordStore + Sync,
    RecordAdapter::Error: Into<ProviderEventsError>,
    IndexAdapter: AsyncIndexStore,
    IndexAdapter::Error: Into<ProviderEventsError>,
{
    let recorded_delivery = WebhookDelivery::new(
        event.repository().provider().repository_provider(),
        event.repository().owner().to_owned(),
        event.repository().name().to_owned(),
        event.delivery_id().as_str().to_owned(),
        unix_now_seconds_lossy(),
    )?;
    if !index_store
        .record_webhook_delivery(&recorded_delivery)
        .await
        .map_err(Into::into)?
    {
        return Ok(duplicate_webhook_outcome(event));
    }

    let outcome = match event.kind() {
        RepositoryWebhookEventKind::RepositoryDeleted => {
            repository::apply_repository_deleted(record_store, index_store, object_store, event)
                .await
        }
        RepositoryWebhookEventKind::RepositoryRenamed { new_repository } => {
            repository::apply_repository_renamed(record_store, index_store, event, new_repository)
                .await
        }
        RepositoryWebhookEventKind::AccessChanged => {
            state::apply_access_changed(
                index_store,
                event,
                recorded_delivery.processed_at_unix_seconds(),
            )
            .await
        }
        RepositoryWebhookEventKind::RevisionPushed { revision } => {
            state::apply_revision_pushed(
                index_store,
                event,
                revision.as_str(),
                recorded_delivery.processed_at_unix_seconds(),
            )
            .await
        }
    };

    match outcome {
        Ok(outcome) => Ok(outcome),
        Err(error) => {
            if let Err(delete_err) = index_store
                .delete_webhook_delivery(&recorded_delivery)
                .await
                .map_err(Into::into)
            {
                tracing::warn!(
                    delivery_id = recorded_delivery.delivery_id(),
                    owner = recorded_delivery.owner(),
                    repo = recorded_delivery.repo(),
                    "failed to remove webhook delivery record for retry: {delete_err}"
                );
            }
            Err(error)
        }
    }
}

use shardline_vcs::RepositoryWebhookEventKind;

use super::ProviderWebhookOutcomeKind;

pub(super) fn duplicate_webhook_event_kind(
    kind: &RepositoryWebhookEventKind,
) -> ProviderWebhookOutcomeKind {
    match kind {
        RepositoryWebhookEventKind::RepositoryDeleted => {
            ProviderWebhookOutcomeKind::RepositoryDeleted
        }
        RepositoryWebhookEventKind::RepositoryRenamed { new_repository } => {
            ProviderWebhookOutcomeKind::RepositoryRenamed {
                new_owner: new_repository.owner().to_owned(),
                new_repo: new_repository.name().to_owned(),
            }
        }
        RepositoryWebhookEventKind::AccessChanged => ProviderWebhookOutcomeKind::AccessChanged,
        RepositoryWebhookEventKind::RevisionPushed { revision } => {
            ProviderWebhookOutcomeKind::RevisionPushed {
                revision: revision.as_str().to_owned(),
            }
        }
    }
}

use std::collections::HashSet;

use serde_json::to_vec;
use shardline_index::{FileRecord, RecordStore, RecordTraversal, RepositoryRecordScope};
use shardline_protocol::RepositoryScope;
use shardline_vcs::RepositoryRef;

use crate::ProviderEventsError;
use shardline_server_core::{
    ServerObjectStore, chunk_object_key, parse_stored_file_record_bytes, provider_directory,
};
use shardline_xet_adapter::{visit_stored_xorb_chunk_hashes, xorb_object_key};

pub(super) async fn ensure_absent_or_matching_record<RecordAdapter>(
    record_store: &RecordAdapter,
    locator: &<RecordAdapter as RecordTraversal>::Locator,
    record: &FileRecord,
) -> Result<(), ProviderEventsError>
where
    RecordAdapter: RecordStore + Sync,
    RecordAdapter::Error: Into<ProviderEventsError>,
{
    if !RecordTraversal::record_locator_exists(record_store, locator)
        .await
        .map_err(Into::into)?
    {
        return Ok(());
    }

    let expected_bytes = to_vec(record)?;
    let existing_bytes = RecordTraversal::read_record_bytes(record_store, locator)
        .await
        .map_err(Into::into)?;
    if existing_bytes == expected_bytes {
        return Ok(());
    }

    Err(ProviderEventsError::ConflictingRenameTargetRecord)
}

pub(super) fn collect_deleted_repository_record_references(
    object_store: &ServerObjectStore,
    record: &FileRecord,
    seen_record_identities: &mut HashSet<String>,
    file_versions: &mut u64,
    chunk_hashes: &mut HashSet<String>,
    held_object_keys: &mut HashSet<String>,
) -> Result<(), ProviderEventsError> {
    if !seen_record_identities.insert(record_identity_key(record)) {
        return Ok(());
    }

    *file_versions = file_versions
        .checked_add(1)
        .ok_or(ProviderEventsError::Overflow)?;
    for chunk in &record.chunks {
        if record.chunk_size == 0 {
            let xorb_object_key = xorb_object_key(&chunk.hash)?;
            held_object_keys.insert(xorb_object_key.as_str().to_owned());
            let mut visit_result = Ok(());
            visit_stored_xorb_chunk_hashes(object_store, &xorb_object_key, |chunk_hash_hex| {
                match chunk_object_key(&chunk_hash_hex) {
                    Ok(chunk_object_key) => {
                        held_object_keys.insert(chunk_object_key.as_str().to_owned());
                        chunk_hashes.insert(chunk_hash_hex);
                        Ok(())
                    }
                    Err(e) => {
                        visit_result = Err(e);
                        Err(shardline_xet_adapter::XetAdapterError::NotFound)
                    }
                }
            })?;
            visit_result?;
            continue;
        }

        chunk_hashes.insert(chunk.hash.clone());
        let chunk_object_key = chunk_object_key(&chunk.hash)?;
        held_object_keys.insert(chunk_object_key.as_str().to_owned());
        let xorb_object_key = xorb_object_key(&chunk.hash)?;
        held_object_keys.insert(xorb_object_key.as_str().to_owned());
    }

    Ok(())
}

pub(super) fn parse_record_entry(bytes: &[u8]) -> Result<FileRecord, ProviderEventsError> {
    Ok(parse_stored_file_record_bytes(bytes)?)
}

pub(super) fn record_belongs_to_repository(
    record: &FileRecord,
    repository: &RepositoryRef,
) -> bool {
    let Some(scope) = record.repository_scope.as_ref() else {
        return false;
    };

    scope.provider() == repository.provider().repository_provider()
        && scope.owner() == repository.owner()
        && scope.name() == repository.name()
}

pub(super) fn repository_record_scope(repository: &RepositoryRef) -> RepositoryRecordScope {
    RepositoryRecordScope::new(
        repository.provider().repository_provider(),
        repository.owner(),
        repository.name(),
    )
}

pub(super) fn renamed_file_record(
    record: &FileRecord,
    new_repository: &RepositoryRef,
) -> Result<FileRecord, ProviderEventsError> {
    let Some(existing_scope) = record.repository_scope.as_ref() else {
        return Ok(record.clone());
    };
    let renamed_scope = RepositoryScope::new(
        new_repository.provider().repository_provider(),
        new_repository.owner(),
        new_repository.name(),
        existing_scope.revision(),
    )
    .map_err(|_error| ProviderEventsError::InvalidProviderWebhookPayload)?;
    let mut renamed_record = record.clone();
    renamed_record.repository_scope = Some(renamed_scope);
    Ok(renamed_record)
}

fn record_identity_key(record: &FileRecord) -> String {
    let repository_scope = record.repository_scope.as_ref().map_or_else(
        || "unscoped".to_owned(),
        |scope| {
            format!(
                "{}:{}/{}@{}",
                provider_directory(scope.provider()),
                scope.owner(),
                scope.name(),
                scope.revision().unwrap_or("latest"),
            )
        },
    );
    format!(
        "{repository_scope}:{}:{}",
        record.file_id, record.content_hash
    )
}

use std::collections::HashSet;

use shardline_index::{
    AsyncIndexStore, FileRecord, RecordMutation, RecordStore, RecordTraversal, RetentionHold,
};
use shardline_protocol::unix_now_seconds_lossy;
use shardline_storage::ObjectKey;
use shardline_vcs::{RepositoryRef, RepositoryWebhookEvent};

use super::{
    DEFAULT_LOCAL_GC_RETENTION_SECONDS, ProviderWebhookOutcome, ProviderWebhookOutcomeKind,
    records::{
        collect_deleted_repository_record_references, ensure_absent_or_matching_record,
        parse_record_entry, record_belongs_to_repository, renamed_file_record,
        repository_record_scope,
    },
    state::migrate_provider_repository_state,
};
use crate::ProviderEventsError;
use shardline_server_core::ServerObjectStore;

pub async fn apply_repository_renamed<RecordAdapter, IndexAdapter>(
    record_store: &RecordAdapter,
    index_store: &IndexAdapter,
    event: &RepositoryWebhookEvent,
    new_repository: &RepositoryRef,
) -> Result<ProviderWebhookOutcome, ProviderEventsError>
where
    RecordAdapter: RecordStore + Sync,
    RecordAdapter::Error: Into<ProviderEventsError>,
    IndexAdapter: AsyncIndexStore,
    IndexAdapter::Error: Into<ProviderEventsError>,
{
    let RepositoryRecords {
        latest_locators: old_latest_locators,
        version_locators: old_version_locators,
        latest_records: _,
        version_records,
    } = collect_repository_records(record_store, event.repository()).await?;
    let mut file_versions = 0_u64;
    let mut chunk_hashes = HashSet::new();
    let renamed_records = version_records
        .iter()
        .map(|record| renamed_file_record(record, new_repository))
        .collect::<Result<Vec<_>, _>>()?;

    for renamed_record in &renamed_records {
        ensure_absent_or_matching_record(
            record_store,
            &RecordTraversal::version_record_locator(record_store, renamed_record),
            renamed_record,
        )
        .await?;
        ensure_absent_or_matching_record(
            record_store,
            &RecordTraversal::latest_record_locator(record_store, renamed_record),
            renamed_record,
        )
        .await?;
    }

    for renamed_record in renamed_records {
        RecordMutation::write_version_record(record_store, &renamed_record)
            .await
            .map_err(Into::into)?;
        RecordMutation::write_latest_record(record_store, &renamed_record)
            .await
            .map_err(Into::into)?;

        file_versions = file_versions
            .checked_add(1)
            .ok_or(ProviderEventsError::Overflow)?;
        for chunk in &renamed_record.chunks {
            chunk_hashes.insert(chunk.hash.clone());
        }
    }

    delete_repository_records(record_store, old_latest_locators, old_version_locators).await?;
    migrate_provider_repository_state(index_store, event.repository(), new_repository).await?;

    Ok(ProviderWebhookOutcome {
        provider: event.repository().provider(),
        owner: event.repository().owner().to_owned(),
        repo: event.repository().name().to_owned(),
        delivery_id: event.delivery_id().as_str().to_owned(),
        event_kind: ProviderWebhookOutcomeKind::RepositoryRenamed {
            new_owner: new_repository.owner().to_owned(),
            new_repo: new_repository.name().to_owned(),
        },
        affected_file_versions: file_versions,
        affected_chunks: u64::try_from(chunk_hashes.len())?,
        applied_holds: 0,
        retention_seconds: None,
    })
}

pub async fn apply_repository_deleted<RecordAdapter, IndexAdapter>(
    record_store: &RecordAdapter,
    index_store: &IndexAdapter,
    object_store: &ServerObjectStore,
    event: &RepositoryWebhookEvent,
) -> Result<ProviderWebhookOutcome, ProviderEventsError>
where
    RecordAdapter: RecordStore + Sync,
    RecordAdapter::Error: Into<ProviderEventsError>,
    IndexAdapter: AsyncIndexStore,
    IndexAdapter::Error: Into<ProviderEventsError>,
{
    let now_unix_seconds = unix_now_seconds_lossy();
    let delete_after_unix_seconds = now_unix_seconds
        .checked_add(DEFAULT_LOCAL_GC_RETENTION_SECONDS)
        .ok_or(ProviderEventsError::Overflow)?;
    let reason = format!(
        "provider repository deletion: {}/{}/{}",
        event.repository().provider().as_str(),
        event.repository().owner(),
        event.repository().name(),
    );
    let RepositoryRecords {
        latest_locators: old_latest_locators,
        version_locators: old_version_locators,
        latest_records,
        version_records,
    } = collect_repository_records(record_store, event.repository()).await?;

    let mut file_versions = 0_u64;
    let mut chunk_hashes = HashSet::new();
    let mut held_object_keys = HashSet::new();
    let mut seen_record_identities = HashSet::new();
    for record in latest_records.iter().chain(&version_records) {
        collect_deleted_repository_record_references(
            object_store,
            record,
            &mut seen_record_identities,
            &mut file_versions,
            &mut chunk_hashes,
            &mut held_object_keys,
        )?;
    }

    let mut applied_holds = 0_u64;
    for object_key in &held_object_keys {
        let hold = RetentionHold::new(
            ObjectKey::parse(object_key)
                .map_err(|_error| ProviderEventsError::InvalidContentHash)?,
            reason.clone(),
            now_unix_seconds,
            Some(delete_after_unix_seconds),
        )?;
        index_store
            .upsert_retention_hold(&hold)
            .await
            .map_err(Into::into)?;
        applied_holds = applied_holds
            .checked_add(1)
            .ok_or(ProviderEventsError::Overflow)?;
    }

    delete_repository_records(record_store, old_latest_locators, old_version_locators).await?;
    let _deleted_state = index_store
        .delete_provider_repository_state(
            event.repository().provider().repository_provider(),
            event.repository().owner(),
            event.repository().name(),
        )
        .await
        .map_err(Into::into)?;

    Ok(ProviderWebhookOutcome {
        provider: event.repository().provider(),
        owner: event.repository().owner().to_owned(),
        repo: event.repository().name().to_owned(),
        delivery_id: event.delivery_id().as_str().to_owned(),
        event_kind: ProviderWebhookOutcomeKind::RepositoryDeleted,
        affected_file_versions: file_versions,
        affected_chunks: u64::try_from(chunk_hashes.len())?,
        applied_holds,
        retention_seconds: Some(DEFAULT_LOCAL_GC_RETENTION_SECONDS),
    })
}

struct RepositoryRecords<Locator> {
    latest_locators: Vec<Locator>,
    version_locators: Vec<Locator>,
    latest_records: Vec<FileRecord>,
    version_records: Vec<FileRecord>,
}

async fn collect_repository_records<RecordAdapter>(
    record_store: &RecordAdapter,
    repository: &RepositoryRef,
) -> Result<RepositoryRecords<RecordAdapter::Locator>, ProviderEventsError>
where
    RecordAdapter: RecordStore + Sync,
    RecordAdapter::Error: Into<ProviderEventsError>,
{
    let repository_scope = repository_record_scope(repository);
    let mut records = RepositoryRecords {
        latest_locators: Vec::new(),
        version_locators: Vec::new(),
        latest_records: Vec::new(),
        version_records: Vec::new(),
    };

    RecordTraversal::visit_repository_latest_records(record_store, &repository_scope, |entry| {
        let record = parse_record_entry(&entry.bytes)?;
        if !record_belongs_to_repository(&record, repository) {
            return Ok::<(), ProviderEventsError>(());
        }

        records.latest_locators.push(entry.locator);
        records.latest_records.push(record);
        Ok(())
    })
    .await?;

    RecordTraversal::visit_repository_version_records(record_store, &repository_scope, |entry| {
        let record = parse_record_entry(&entry.bytes)?;
        if !record_belongs_to_repository(&record, repository) {
            return Ok::<(), ProviderEventsError>(());
        }

        records.version_locators.push(entry.locator);
        records.version_records.push(record);
        Ok(())
    })
    .await?;

    Ok(records)
}

async fn delete_repository_records<RecordAdapter>(
    record_store: &RecordAdapter,
    old_latest_locators: Vec<RecordAdapter::Locator>,
    old_version_locators: Vec<RecordAdapter::Locator>,
) -> Result<(), ProviderEventsError>
where
    RecordAdapter: RecordStore + Sync,
    RecordAdapter::Error: Into<ProviderEventsError>,
{
    for locator in old_latest_locators {
        RecordMutation::delete_record_locator(record_store, &locator)
            .await
            .map_err(Into::into)?;
    }
    for locator in old_version_locators {
        RecordMutation::delete_record_locator(record_store, &locator)
            .await
            .map_err(Into::into)?;
    }
    RecordMutation::prune_empty_latest_records(record_store)
        .await
        .map_err(Into::into)?;
    Ok(())
}

