            "version_path_mismatch"
        );
        assert_eq!(
            IndexRebuildIssueKind::InvalidVersionReconstructionPlan.as_str(),
            "invalid_version_reconstruction_plan"
        );
        assert_eq!(
            IndexRebuildIssueKind::InvalidRetainedShard.as_str(),
            "invalid_retained_shard"
        );
