    }

    #[test]
    fn write_field_name_second_field_adds_comma() {
        let mut buf = Vec::new();
        let mut first = true;

        write_field_name(&mut buf, "first", &mut first).unwrap();
        write_field_name(&mut buf, "second", &mut first).unwrap();

        assert!(!first);
        assert_eq!(String::from_utf8(buf).unwrap(), r#""first":,"second":"#);
