impl LocalBackend {
    pub(crate) fn put_object_bytes_if_absent(
        &self,
        object_key: &ObjectKey,
        bytes: Vec<u8>,
    ) -> Result<PutOutcome, ServerError> {
        tokio::task::block_in_place(|| {
            let integrity =
                ObjectIntegrity::new(super::chunk_hash(&bytes), u64::try_from(bytes.len())?);
            Ok(self.object_store().put_if_absent(
                object_key,
                ObjectBody::from_vec(bytes),
                &integrity,
            )?)
        })
    }

    pub(crate) fn put_sha256_addressed_object_bytes_if_absent(
        &self,
        object_key: &ObjectKey,
        digest_hex: &str,
        bytes: Vec<u8>,
    ) -> Result<PutOutcome, ServerError> {
        tokio::task::block_in_place(|| {
            let canonical_key = shared_sha256_object_key(digest_hex)?;
            let integrity =
                ObjectIntegrity::new(super::chunk_hash(&bytes), u64::try_from(bytes.len())?);
            let canonical_outcome = self.object_store().put_if_absent(
                &canonical_key,
                ObjectBody::from_vec(bytes),
                &integrity,
            )?;
            if canonical_key == *object_key {
                return Ok(canonical_outcome);
            }
            Ok(self
                .object_store()
                .copy_if_absent(&canonical_key, object_key)?)
        })
    }

    pub(crate) fn copy_object_if_absent(
        &self,
        source: &ObjectKey,
        destination: &ObjectKey,
    ) -> Result<PutOutcome, ServerError> {
        tokio::task::block_in_place(|| {
            Ok(self.object_store().copy_if_absent(source, destination)?)
        })
    }

    pub(crate) fn put_object_bytes_overwrite(
        &self,
        object_key: &ObjectKey,
        bytes: Vec<u8>,
    ) -> Result<(), ServerError> {
        tokio::task::block_in_place(|| {
            let integrity =
                ObjectIntegrity::new(super::chunk_hash(&bytes), u64::try_from(bytes.len())?);
            Ok(self.object_store().put_overwrite(
                object_key,
                ObjectBody::from_vec(bytes),
                &integrity,
            )?)
        })
    }

    pub(crate) fn put_sha256_addressed_object_file(
        &self,
        object_key: &ObjectKey,
        digest_hex: &str,
        path: &std::path::Path,
        integrity: &ObjectIntegrity,
    ) -> Result<PutOutcome, ServerError> {
        tokio::task::block_in_place(|| {
            let canonical_key = shared_sha256_object_key(digest_hex)?;
            let canonical_outcome =
                self.object_store()
                    .put_content_addressed_file(&canonical_key, path, integrity)?;
            if canonical_key == *object_key {
                return Ok(canonical_outcome);
            }
            Ok(self
                .object_store()
                .copy_if_absent(&canonical_key, object_key)?)
        })
    }

    pub(crate) async fn object_length(&self, object_key: &ObjectKey) -> Result<u64, ServerError> {
        let object_store = self.object_store();
        let object_key = object_key.clone();
        tokio::task::spawn_blocking(move || {
            let metadata = object_store.metadata(&object_key)?;
            let Some(metadata) = metadata else {
                return Err(ServerError::NotFound);
            };
            Ok(metadata.length())
        })
        .await
        .map_err(ServerError::BlockingTask)?
    }

    pub(crate) async fn read_object(&self, object_key: &ObjectKey) -> Result<Vec<u8>, ServerError> {
        let object_store = self.object_store();
        let metadata = object_store.metadata(object_key)?;
        let Some(metadata) = metadata else {
            return Err(ServerError::NotFound);
        };
        let object_key = object_key.clone();
        tokio::task::spawn_blocking(move || {
            read_full_object(&object_store, &object_key, metadata.length())
        })
        .await
        .map_err(ServerError::BlockingTask)?
    }

    pub(crate) async fn read_object_stream(
        &self,
        object_key: &ObjectKey,
        total_length: u64,
        range: Option<ByteRange>,
    ) -> Result<ServerByteStream, ServerError> {
        let object_store = self.object_store();
        if let Some(range) = range {
            return object_byte_range_stream(object_store, object_key.clone(), total_length, range)
                .await;
        }

        object_byte_stream(object_store, object_key.clone(), total_length).await
    }

    pub(crate) fn visit_object_prefix<Visitor>(
        &self,
        prefix: &ObjectPrefix,
        visitor: Visitor,
    ) -> Result<(), ServerError>
    where
        Visitor: FnMut(ObjectMetadata) -> Result<(), ServerError>,
    {
        tokio::task::block_in_place(|| {
            crate::object_store::visit_object_prefix(&self.object_store(), prefix, visitor)
        })
    }

    pub(crate) fn list_object_flat_namespace_page(
        &self,
        prefix: &ObjectPrefix,
        start_after: Option<&ObjectKey>,
        limit: usize,
    ) -> Result<Vec<ObjectMetadata>, ServerError> {
        tokio::task::block_in_place(|| {
            Ok(self
                .object_store()
                .list_flat_namespace_page(prefix, start_after, limit)?)
        })
    }

    pub(crate) async fn delete_object_if_present(
        &self,
        object_key: &ObjectKey,
    ) -> Result<DeleteOutcome, ServerError> {
        let object_store = self.object_store();
        let object_key = object_key.clone();
        tokio::task::spawn_blocking(move || Ok(object_store.delete_if_present(&object_key)?))
            .await
            .map_err(ServerError::BlockingTask)?
    }
}

use std::io::ErrorKind;

use shardline_index::{
    FileRecord, LocalIndexStoreError, LocalRecordStore, RecordTraversal, RepositoryRecordScope,
};
use shardline_protocol::RepositoryScope;

use crate::{
    ServerError,
    error::IndexError,
    record_store::parse_stored_file_record_bytes,
    validation::{validate_content_hash, validate_identifier},
};

pub(super) async fn read_record(
    record_store: &LocalRecordStore,
    file_id: &str,
    content_hash: Option<&str>,
    repository_scope: Option<&RepositoryScope>,
) -> Result<FileRecord, ServerError> {
    validate_identifier(file_id)?;
    let bytes = if let Some(hash) = content_hash {
        validate_content_hash(hash)?;
        let record = FileRecord {
            file_id: file_id.to_owned(),
            content_hash: hash.to_owned(),
            total_bytes: 0,
            chunk_size: 0,
            repository_scope: repository_scope.cloned(),
            chunks: Vec::new(),
        };
        let locator = RecordTraversal::version_record_locator(record_store, &record);
        read_record_bytes(record_store, &locator).await?
    } else {
        let record = FileRecord {
            file_id: file_id.to_owned(),
            content_hash: String::new(),
            total_bytes: 0,
            chunk_size: 0,
            repository_scope: repository_scope.cloned(),
            chunks: Vec::new(),
        };
        let locator = RecordTraversal::latest_record_locator(record_store, &record);
        read_record_bytes(record_store, &locator).await?
    };
    parse_stored_file_record_bytes(&bytes)
}

async fn read_record_bytes(
    record_store: &LocalRecordStore,
    locator: &<LocalRecordStore as RecordTraversal>::Locator,
) -> Result<Vec<u8>, ServerError> {
    match RecordTraversal::read_record_bytes(record_store, locator).await {
        Ok(bytes) => Ok(bytes),
        Err(LocalIndexStoreError::Io(error)) if error.kind() == ErrorKind::NotFound => {
            Err(ServerError::NotFound)
        }
        Err(error) => Err(ServerError::Index(IndexError::Local(error))),
    }
}

pub(super) async fn repository_references_xorb(
    record_store: &LocalRecordStore,
    hash_hex: &str,
    repository_scope: &RepositoryScope,
) -> Result<bool, ServerError> {
    let repository = RepositoryRecordScope::from_repository_scope(repository_scope);
    let mut found = false;
    record_store
        .visit_repository_latest_records(&repository, |entry| {
            inspect_repository_record_for_xorb(&mut found, &entry.bytes, hash_hex, repository_scope)
        })
        .await?;
    if found {
        return Ok(true);
    }
    record_store
        .visit_repository_version_records(&repository, |entry| {
            inspect_repository_record_for_xorb(&mut found, &entry.bytes, hash_hex, repository_scope)
        })
        .await?;

    Ok(found)
}

fn inspect_repository_record_for_xorb(
    found: &mut bool,
    bytes: &[u8],
    hash_hex: &str,
    repository_scope: &RepositoryScope,
) -> Result<(), ServerError> {
    if *found {
        return Ok(());
    }
    let record = parse_stored_file_record_bytes(bytes)?;
    if record.repository_scope.as_ref() == Some(repository_scope)
        && record.chunks.iter().any(|chunk| chunk.hash == hash_hex)
    {
        *found = true;
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use serde_json::to_vec;
    use shardline_index::{FileChunkRecord, FileRecord};
    use shardline_protocol::{RepositoryProvider, RepositoryScope};

    use super::inspect_repository_record_for_xorb;

    fn make_scope() -> RepositoryScope {
        RepositoryScope::new(RepositoryProvider::GitHub, "owner", "repo", None).unwrap()
    }

    fn make_other_scope() -> RepositoryScope {
        RepositoryScope::new(RepositoryProvider::GitHub, "other-owner", "repo", None).unwrap()
    }

    fn make_record(scope: &RepositoryScope, chunk_hash: &str) -> FileRecord {
        FileRecord {
            file_id: "test.txt".to_owned(),
            content_hash: "deadbeef".to_owned(),
            total_bytes: 100,
            chunk_size: 64,
            repository_scope: Some(scope.clone()),
            chunks: vec![FileChunkRecord {
                hash: chunk_hash.to_owned(),
                offset: 0,
                length: 100,
                range_start: 0,
                range_end: 1,
                packed_start: 0,
                packed_end: 0,
            }],
        }
    }

    #[test]
    fn matching_hash_and_scope() {
        let scope = make_scope();
        let record = make_record(&scope, "abc123");
        let bytes = to_vec(&record).unwrap();

        let mut found = false;
        inspect_repository_record_for_xorb(&mut found, &bytes, "abc123", &scope).unwrap();
        assert!(found);
    }

    #[test]
    fn matching_hash_wrong_scope() {
        let scope = make_scope();
        let record = make_record(&scope, "abc123");
        let bytes = to_vec(&record).unwrap();

        let mut found = false;
        let other = make_other_scope();
        inspect_repository_record_for_xorb(&mut found, &bytes, "abc123", &other).unwrap();
        assert!(!found);
    }

    #[test]
    fn different_hash() {
        let scope = make_scope();
        let record = make_record(&scope, "abc123");
        let bytes = to_vec(&record).unwrap();

        let mut found = false;
        inspect_repository_record_for_xorb(&mut found, &bytes, "xyz789", &scope).unwrap();
        assert!(!found);
    }

    #[test]
    fn already_found() {
        let scope = make_scope();
        let mut found = true;

        // When found is already true, the function returns early without parsing,
        // so even garbage bytes are fine.
        inspect_repository_record_for_xorb(&mut found, b"not valid json", "anything", &scope)
            .unwrap();
        assert!(found);
    }

    #[test]
    fn invalid_bytes() {
        let scope = make_scope();
        let mut found = false;

        let result =
            inspect_repository_record_for_xorb(&mut found, b"not valid json", "anything", &scope);
        assert!(result.is_err());
    }
}

