use axum::body::Bytes;
use shardline_protocol::{ByteRange, RepositoryScope};
use shardline_storage::ObjectStore;

use super::LocalBackend;
use crate::{
    ServerError,
    download_stream::{ServerByteStream, object_byte_range_stream, object_byte_stream},
    upload_ingest::RequestBodyReader,
    xet_adapter::{
        XorbUploadResponse, resolve_dedupe_shard_object, store_uploaded_xorb_bytes, xorb_object_key,
    },
};

impl LocalBackend {
    /// Stores a raw xorb body under its content hash.
    ///
    /// # Errors
    ///
    /// Returns [`ServerError`] when the supplied hash is invalid, the body hash does not
    /// match, or persistence fails.
    pub async fn upload_xorb(
        &self,
        expected_hash: &str,
        body: Bytes,
    ) -> Result<XorbUploadResponse, ServerError> {
        self.upload_xorb_stream(expected_hash, RequestBodyReader::from_bytes(body))
            .await
    }

    /// Stores a bounded raw xorb body under its content hash.
    ///
    /// # Errors
    ///
    /// Returns [`ServerError`] when request streaming, hash validation, or persistence
    /// fails.
    pub(crate) async fn upload_xorb_stream(
        &self,
        expected_hash: &str,
        mut body: RequestBodyReader,
    ) -> Result<XorbUploadResponse, ServerError> {
        let uploaded_body = crate::upload_ingest::read_body_to_bytes(&mut body).await?;
        let object_store = self.object_store();
        store_uploaded_xorb_bytes(&object_store, expected_hash, &uploaded_body)
            .map_err(ServerError::from)
    }

    pub(crate) async fn read_dedupe_shard_stream(
        &self,
        hash_hex: &str,
    ) -> Result<(ServerByteStream, u64), ServerError> {
        let object_store = self.object_store();
        let (object_key, total_length) =
            resolve_dedupe_shard_object(&self.index_store, &object_store, hash_hex).await?;
        let byte_stream = object_byte_stream(object_store, object_key, total_length).await?;

        Ok((byte_stream, total_length))
    }

    /// Streams a stored xorb byte range by hash.
    ///
    /// # Errors
    ///
    /// Returns [`ServerError`] when the hash is invalid, the xorb is missing, or the
    /// requested byte range cannot be served.
    pub(crate) async fn read_xorb_range_stream(
        &self,
        hash_hex: &str,
        total_length: u64,
        range: ByteRange,
    ) -> Result<ServerByteStream, ServerError> {
        let object_store = self.object_store();
        let object_key = xorb_object_key(hash_hex)?;

        object_byte_range_stream(object_store, object_key, total_length, range).await
    }

    /// Loads the stored byte length for a serialized xorb object.
    ///
    /// # Errors
    ///
    /// Returns [`ServerError`] when the hash is invalid or the xorb is missing.
    pub async fn xorb_length(&self, hash_hex: &str) -> Result<u64, ServerError> {
        let object_store = self.object_store();
        let object_key = xorb_object_key(hash_hex)?;
        let metadata = object_store.metadata(&object_key)?;
        let Some(metadata) = metadata else {
            return Err(ServerError::NotFound);
        };

        Ok(metadata.length())
    }

    pub(crate) async fn repository_references_xorb(
        &self,
        hash_hex: &str,
        repository_scope: &RepositoryScope,
    ) -> Result<bool, ServerError> {
        super::records::repository_references_xorb(&self.record_store, hash_hex, repository_scope)
            .await
    }
}

#[cfg(test)]
mod tests {
    use std::fs::metadata;
    #[cfg(unix)]
    use std::os::unix::fs::PermissionsExt;

    #[cfg(unix)]
    use shardline_storage::anchored_fs::{
        AnchoredPathOptions, open_anchored_target as open_anchored_target_shared,
        write_anchored_temporary_file as write_anchored_temporary_file_shared,
    };
    #[cfg(unix)]
    use std::{fs::rename, io, path::Path};

    #[cfg(unix)]
    const LOCAL_DIRECTORY_MODE: u32 = 0o700;
    #[cfg(unix)]
    const LOCAL_FILE_MODE: u32 = 0o600;

    #[cfg(unix)]
    fn anchored_path_options() -> AnchoredPathOptions {
        AnchoredPathOptions::new(Some(LOCAL_DIRECTORY_MODE), Some(LOCAL_FILE_MODE))
    }

    #[cfg(unix)]
    fn write_file_atomically(root: &Path, path: &Path, bytes: &[u8]) -> io::Result<()> {
        use shardline_storage::anchored_fs::remove_if_present;

        let anchored = open_anchored_target_shared(root, path, anchored_path_options(), || {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local filesystem path must remain under the configured root",
            )
        })?;
        let temporary = write_anchored_temporary_file_shared(
            &anchored,
            bytes,
            anchored_path_options().file_mode,
        )?;
        let final_path = anchored.final_path();
        match rename(&temporary, &final_path) {
            Ok(()) => {}
            Err(error) => {
                remove_if_present(&temporary)?;
                return Err(error);
            }
        }

        Ok(())
    }

    #[cfg(unix)]
    #[test]
    fn write_file_atomically_creates_private_file_and_directory_modes() {
        let sandbox = tempfile::tempdir();
        assert!(sandbox.is_ok());
        let Ok(sandbox) = sandbox else {
            return;
        };
        let root = sandbox.path().join("root");
        let path = root.join("nested").join("record.json");

        let wrote = write_file_atomically(&root, &path, br#"{"ok":true}"#);
        assert!(wrote.is_ok());

        let file_metadata = metadata(&path);
        assert!(file_metadata.is_ok());
        let Ok(file_metadata) = file_metadata else {
            return;
        };
        let directory_metadata = metadata(root.join("nested"));
        assert!(directory_metadata.is_ok());
        let Ok(directory_metadata) = directory_metadata else {
            return;
        };

        assert_eq!(file_metadata.permissions().mode() & 0o777, 0o600);
        assert_eq!(directory_metadata.permissions().mode() & 0o777, 0o700);
    }
}

use std::{
    io::{Error, ErrorKind},
    path::Path,
};

use shardline_storage::{
    DirectoryPathError,
    ensure_directory_path_components_are_not_symlinked as ensure_directory_path_components_are_not_symlinked_shared,
};

use crate::ServerError;

pub(crate) fn ensure_directory_path_components_are_not_symlinked(
    path: &Path,
) -> Result<(), ServerError> {
    ensure_directory_path_components_are_not_symlinked_shared(path)
        .map_err(map_directory_path_error)
}

fn map_directory_path_error(error: DirectoryPathError) -> ServerError {
    match error {
        DirectoryPathError::UnsupportedPrefix => ServerError::Io(Error::new(
            ErrorKind::InvalidInput,
            "directory path contains an unsupported prefix component",
        )),
        DirectoryPathError::SymlinkedComponent(path) => ServerError::Io(Error::new(
            ErrorKind::InvalidData,
            format!(
                "directory path contains a symlinked component: {}",
                path.display()
            ),
        )),
        DirectoryPathError::NonDirectoryComponent(path) => ServerError::Io(Error::new(
            ErrorKind::InvalidData,
            format!(
                "directory path contains a non-directory component: {}",
                path.display()
            ),
        )),
        DirectoryPathError::Io(error) => ServerError::Io(error),
    }
}

#[cfg(test)]
mod tests {
    use std::io::{Error, ErrorKind};
    use std::path::PathBuf;

    use shardline_storage::DirectoryPathError;

    use crate::ServerError;

    #[test]
    fn map_unsupported_prefix() {
        let result = super::map_directory_path_error(DirectoryPathError::UnsupportedPrefix);
        assert!(
            matches!(&result, ServerError::Io(e) if e.kind() == ErrorKind::InvalidInput),
            "expected Io(InvalidInput), got {result:?}"
        );
    }

    #[test]
    #[allow(clippy::wildcard_enum_match_arm, clippy::panic)]
    fn map_symlinked_component() {
        let path = PathBuf::from("/test");
        let result =
            super::map_directory_path_error(DirectoryPathError::SymlinkedComponent(path));
        let msg = match &result {
            ServerError::Io(e) if e.kind() == ErrorKind::InvalidData => e.to_string(),
            other => panic!("expected Io(InvalidData), got {other:?}"),
        };
        assert!(
            msg.contains("/test"),
            "expected message to contain the path, got: {msg}"
        );
    }

    #[test]
    #[allow(clippy::wildcard_enum_match_arm, clippy::panic)]
    fn map_non_directory_component() {
        let path = PathBuf::from("/test");
        let result =
            super::map_directory_path_error(DirectoryPathError::NonDirectoryComponent(path));
        match result {
            ServerError::Io(e) if e.kind() == ErrorKind::InvalidData => {
                // expected
            }
            other => panic!("expected Io(InvalidData), got {other:?}"),
        }
    }

    #[test]
    #[allow(clippy::wildcard_enum_match_arm, clippy::panic)]
    fn map_io_error() {
        let io_err = Error::new(ErrorKind::NotFound, "test");
        let result = super::map_directory_path_error(DirectoryPathError::Io(io_err));
        match result {
            ServerError::Io(e) if e.kind() == ErrorKind::NotFound => {
                // expected
            }
            other => panic!("expected Io(NotFound), got {other:?}"),
        }
    }
}

