        assert_eq!(buf.len(), 0);
    }

    #[test]
    fn shared_chunk_buffer_empty() {
        let buf = ChunkBuffer::Shared(Bytes::new());
        assert_eq!(buf.as_slice(), b"");
        assert_eq!(buf.len(), 0);
    }

    // ------------------------------------------------------------------
    // RequestBodyReader::from_bytes
    // ------------------------------------------------------------------

    #[tokio::test]
    async fn from_bytes_returns_content_on_first_call() {
        let mut reader = RequestBodyReader::from_bytes(Bytes::from_static(b"hello"));
        let chunk = reader.next_bytes().await.unwrap();
        assert!(chunk.is_some());
        assert_eq!(chunk.unwrap().as_ref(), b"hello");
    }

    #[tokio::test]
    async fn from_bytes_returns_none_on_second_call() {
        let mut reader = RequestBodyReader::from_bytes(Bytes::from_static(b"hello"));
        let _first = reader.next_bytes().await.unwrap();
        let second = reader.next_bytes().await.unwrap();
        assert!(second.is_none());
    }

    #[tokio::test]
    async fn from_bytes_empty_body_returns_empty_chunk_then_none() {
        // `from_bytes` wraps data in `stream::once`, so even an empty Bytes
        // yields one `Some(Bytes::new())` before the stream ends.
        let mut reader = RequestBodyReader::from_bytes(Bytes::new());
        let result = reader.next_bytes().await.unwrap();
        assert!(result.is_some());
        assert!(result.unwrap().is_empty());
        assert!(reader.next_bytes().await.unwrap().is_none());
    }

    #[tokio::test]
    async fn from_bytes_large_content() {
        let data = vec![0xAB_u8; 65536];
        let bytes = Bytes::from(data.clone());
        let mut reader = RequestBodyReader::from_bytes(bytes);

        let chunk = reader.next_bytes().await.unwrap();
        assert!(chunk.is_some());
        assert_eq!(chunk.unwrap().as_ref(), data.as_slice());

        // Stream exhausted.
        assert!(reader.next_bytes().await.unwrap().is_none());
    }

    #[tokio::test]
    async fn from_bytes_multiple_chunks_are_none_after_exhaustion() {
        // from_bytes produces a single-chunk stream
        let mut reader = RequestBodyReader::from_bytes(Bytes::from_static(b"only one chunk"));
        assert!(reader.next_bytes().await.unwrap().is_some());
        assert!(reader.next_bytes().await.unwrap().is_none());
        assert!(reader.next_bytes().await.unwrap().is_none());
    }

    // ------------------------------------------------------------------
    // read_body_to_bytes
    // ------------------------------------------------------------------

    #[tokio::test]
    async fn read_body_to_bytes_returns_full_content() {
        let mut reader = RequestBodyReader::from_bytes(Bytes::from_static(b"hello world"));
        let body = read_body_to_bytes(&mut reader).await.unwrap();
        assert_eq!(body, b"hello world");
    }

    #[tokio::test]
    async fn read_body_to_bytes_empty_body() {
        let mut reader = RequestBodyReader::from_bytes(Bytes::new());
        let body = read_body_to_bytes(&mut reader).await.unwrap();
        assert!(body.is_empty());
    }

    #[tokio::test]
    async fn read_body_to_bytes_large_content() {
        let data = vec![0xCD_u8; 100_000];
        let mut reader = RequestBodyReader::from_bytes(Bytes::from(data.clone()));
        let body = read_body_to_bytes(&mut reader).await.unwrap();
        assert_eq!(body, data.as_slice());
    }

    // ------------------------------------------------------------------
    // RequestBodyReader::from_body size-limit path
    // ------------------------------------------------------------------

    #[test]
    fn from_body_rejects_body_exceeding_size_hint() {
        use std::num::NonZeroUsize;

        use axum::body::Body;

        let body = Body::from(vec![0u8; 100]);
        let max_bytes = NonZeroUsize::new(50).unwrap();
        let result = RequestBodyReader::from_body(body, max_bytes);
        assert!(result.is_err());
    }

    #[test]
    fn from_body_accepts_body_within_size_hint() {
        use std::num::NonZeroUsize;

        use axum::body::Body;

        let body = Body::from(vec![0u8; 50]);
        let max_bytes = NonZeroUsize::new(100).unwrap();
        let result = RequestBodyReader::from_body(body, max_bytes);
        assert!(result.is_ok());
    }

    // ------------------------------------------------------------------
    // Edge cases
    // ------------------------------------------------------------------

    #[tokio::test]
    async fn read_body_to_bytes_idempotent_with_empty_reader() {
        let mut reader = RequestBodyReader::from_bytes(Bytes::new());
        let body1 = read_body_to_bytes(&mut reader).await.unwrap();
        let body2 = read_body_to_bytes(&mut reader).await.unwrap();
        assert!(body1.is_empty());
        assert!(body2.is_empty());
    }

    #[test]
    fn chunk_buffer_len_matches_as_slice() {
        let data = b"chunk data for testing";
        let pooled = ChunkBuffer::Pooled(Bytes::from_static(data));
        let shared = ChunkBuffer::Shared(Bytes::from_static(data));
        assert_eq!(pooled.len(), pooled.as_slice().len());
        assert_eq!(shared.len(), shared.as_slice().len());
        assert_eq!(pooled.len(), shared.len());
    }
}

use axum::body::Bytes;
use bytes::BytesMut;
use shardline_storage::{ObjectBody, ObjectIntegrity, ObjectKey, ObjectStore, PutOutcome};
use tokio::task;

use super::body_reader::ChunkBuffer;
use crate::{
    ServerError, chunk_store::chunk_object_key_for_computed_hash, local_backend::chunk_hash,
    object_store::ServerObjectStore,
};

pub(super) struct SequencedStoredChunkOutcome {
    pub(super) sequence: u64,
    pub(super) offset: u64,
    pub(super) stored: StoredChunkOutcome,
}

pub(super) struct SequencedStoredChunkTaskOutcome {
    pub(super) sequence: u64,
    pub(super) offset: u64,
    pub(super) stored: StoredChunkOutcome,
    pub(super) reusable_buffer: Option<BytesMut>,
}

pub(super) struct StoredChunkOutcome {
    pub(super) hash_hex: String,
    pub(super) chunk_length: u64,
    pub(super) inserted: bool,
}

struct ChunkStorageRequest {
    key: ObjectKey,
    integrity: ObjectIntegrity,
    hash_hex: String,
    chunk_length: u64,
}

fn chunk_object_key_and_integrity(chunk: &ChunkBuffer) -> Result<ChunkStorageRequest, ServerError> {
    let hash = chunk_hash(chunk.as_slice());
    let (hash_hex, object_key) = chunk_object_key_for_computed_hash(hash)?;
    let chunk_length = u64::try_from(chunk.len())?;
    let integrity = ObjectIntegrity::new(hash, chunk_length);
    Ok(ChunkStorageRequest {
        key: object_key,
        integrity,
        hash_hex,
        chunk_length,
    })
}

pub(super) async fn put_if_absent_chunk_buffer(
    object_store: &ServerObjectStore,
    chunk: ChunkBuffer,
) -> Result<StoredChunkOutcome, ServerError> {
    let request = chunk_object_key_and_integrity(&chunk)?;
    match chunk {
        ChunkBuffer::Pooled(bytes) => {
            let (outcome, _bytes) =
                put_if_absent_pooled_bytes(object_store, &request, bytes).await?;
            Ok(StoredChunkOutcome {
                hash_hex: request.hash_hex,
                chunk_length: request.chunk_length,
                inserted: matches!(outcome, PutOutcome::Inserted),
            })
        }
        ChunkBuffer::Shared(bytes) => {
            let outcome = put_if_absent_shared_bytes(object_store, &request, bytes).await?;
            Ok(StoredChunkOutcome {
                hash_hex: request.hash_hex,
                chunk_length: request.chunk_length,
                inserted: matches!(outcome, PutOutcome::Inserted),
            })
        }
    }
}

pub(super) async fn put_if_absent_pooled_chunk_buffer(
    object_store: &ServerObjectStore,
    chunk: ChunkBuffer,
) -> Result<(StoredChunkOutcome, Option<BytesMut>), ServerError> {
    let request = chunk_object_key_and_integrity(&chunk)?;
    let bytes = match chunk {
        ChunkBuffer::Pooled(bytes) => bytes,
        ChunkBuffer::Shared(_bytes) => return Err(ServerError::Overflow),
    };
    let (outcome, bytes) = put_if_absent_pooled_bytes(object_store, &request, bytes).await?;
    let reusable_buffer = bytes.try_into_mut().ok();
    Ok((
        StoredChunkOutcome {
            hash_hex: request.hash_hex,
            chunk_length: request.chunk_length,
            inserted: matches!(outcome, PutOutcome::Inserted),
        },
        reusable_buffer,
    ))
}

async fn put_if_absent_shared_bytes(
    object_store: &ServerObjectStore,
    request: &ChunkStorageRequest,
    bytes: Bytes,
) -> Result<PutOutcome, ServerError> {
    match object_store {
        ServerObjectStore::Local(store) => {
            let store = store.clone();
            let key = request.key.clone();
            let integrity = request.integrity;
            task::spawn_blocking(move || {
                store
                    .put_if_absent(&key, ObjectBody::from_bytes(bytes), &integrity)
                    .map_err(ServerError::from)
            })
            .await
            .map_err(ServerError::BlockingTask)?
        }
        ServerObjectStore::S3(store) => {
            let store = store.clone();
            let key = request.key.clone();
            let integrity = request.integrity;
            task::spawn_blocking(move || {
                store
                    .put_if_absent(&key, ObjectBody::from_bytes(bytes), &integrity)
                    .map_err(ServerError::from)
            })
            .await
            .map_err(ServerError::BlockingTask)?
        }
        ServerObjectStore::Blackhole => Ok(object_store.put_if_absent(
            &request.key,
            ObjectBody::from_bytes(bytes),
            &request.integrity,
        )?),
    }
}

async fn put_if_absent_pooled_bytes(
    object_store: &ServerObjectStore,
    request: &ChunkStorageRequest,
    bytes: Bytes,
) -> Result<(PutOutcome, Bytes), ServerError> {
    match object_store {
        ServerObjectStore::Local(store) => {
            let store = store.clone();
            let key = request.key.clone();
            let integrity = request.integrity;
            task::spawn_blocking(move || {
                let outcome = store
                    .put_if_absent(&key, ObjectBody::from_bytes(bytes.clone()), &integrity)
                    .map_err(ServerError::from)?;
                Ok((outcome, bytes))
            })
            .await
            .map_err(ServerError::BlockingTask)?
        }
        ServerObjectStore::S3(store) => {
            let store = store.clone();
            let key = request.key.clone();
            let integrity = request.integrity;
            task::spawn_blocking(move || {
                let outcome = store
                    .put_if_absent(&key, ObjectBody::from_bytes(bytes.clone()), &integrity)
                    .map_err(ServerError::from)?;
                Ok((outcome, bytes))
            })
            .await
            .map_err(ServerError::BlockingTask)?
        }
        ServerObjectStore::Blackhole => {
            let outcome = object_store.put_if_absent(
                &request.key,
                ObjectBody::from_bytes(bytes.clone()),
                &request.integrity,
            )?;
            Ok((outcome, bytes))
        }
    }
}

