use std::num::NonZeroU64;

use shardline_protocol::{
    RepositoryProvider, RepositoryScope, TokenClaims, TokenScope, TokenSigner,
};
use shardline_vcs::{
    GrantedRepositoryAccess, ProviderKind, ProviderSubject, RepositoryAccess, RepositoryRef,
    RevisionRef,
};

const SIGNING_KEY: &[u8] = b"test-integration-signing-key-32bytes!!";

fn make_grant(
    provider: ProviderKind,
    owner: &str,
    name: &str,
    revision: &str,
    subject: &str,
    access: RepositoryAccess,
) -> GrantedRepositoryAccess {
    let repository = RepositoryRef::new(provider, owner, name).expect("valid repository ref");
    let rev = RevisionRef::new(revision).expect("valid revision ref");
    let sub = ProviderSubject::new(subject).expect("valid subject");
    GrantedRepositoryAccess::from_decision(
        &shardline_vcs::AuthorizationRequest::new(sub.clone(), repository, rev, access),
        shardline_vcs::AuthorizationDecision::Allow(sub),
    )
    .expect("allow decision should produce a grant")
}

#[test]
fn token_issuance_roundtrip_verifies_with_same_key() {
    let issuer = shardline_vcs::ProviderTokenIssuer::new(
        "test-issuer",
        SIGNING_KEY,
        NonZeroU64::new(300).expect("nonzero"),
    )
    .expect("valid issuer");
    let grant = make_grant(
        ProviderKind::GitHub,
        "acme",
        "assets",
        "refs/heads/main",
        "user-1",
        RepositoryAccess::Read,
    );

    let issued = issuer
        .issue_at(&grant, 1_000)
        .expect("issuance should succeed");

    assert_eq!(issued.claims().issuer(), "test-issuer");
    assert_eq!(issued.claims().subject(), "user-1");
    assert_eq!(issued.claims().expires_at_unix_seconds(), 1_300);

    let signer = TokenSigner::new(SIGNING_KEY).expect("valid signer");
    let verified = signer
        .verify_at(issued.token(), 1_000)
        .expect("verification should succeed");

    assert_eq!(verified.issuer(), "test-issuer");
    assert_eq!(verified.subject(), "user-1");
    assert_eq!(verified.scope(), TokenScope::Read);
    assert_eq!(verified.repository().owner(), "acme");
    assert_eq!(verified.repository().name(), "assets");
    assert_eq!(verified.repository().revision(), Some("refs/heads/main"));
}

#[test]
fn token_verification_rejects_wrong_key() {
    let issuer = shardline_vcs::ProviderTokenIssuer::new(
        "test-issuer",
        SIGNING_KEY,
        NonZeroU64::new(60).expect("nonzero"),
    )
    .expect("valid issuer");
    let grant = make_grant(
        ProviderKind::GitLab,
        "team",
        "repo",
        "refs/tags/v1.0",
        "user-2",
        RepositoryAccess::Write,
    );

    let issued = issuer
        .issue_at(&grant, 500)
        .expect("issuance should succeed");

    let wrong_key = b"wrong-signing-key-different-32bytes!!";
    let wrong_signer = TokenSigner::new(wrong_key).expect("valid wrong signer");
    let result = wrong_signer.verify_at(issued.token(), 500);

    assert!(result.is_err(), "verification with wrong key should fail");
}

#[test]
fn token_verification_rejects_expired_token() {
    let issuer = shardline_vcs::ProviderTokenIssuer::new(
        "test-issuer",
        SIGNING_KEY,
        NonZeroU64::new(10).expect("nonzero"),
    )
    .expect("valid issuer");
    let grant = make_grant(
        ProviderKind::Generic,
        "org",
        "project",
        "main",
        "user-3",
        RepositoryAccess::Read,
    );

    let issued = issuer
        .issue_at(&grant, 100)
        .expect("issuance should succeed");

    let signer = TokenSigner::new(SIGNING_KEY).expect("valid signer");
    let result = signer.verify_at(issued.token(), 200);

    assert!(result.is_err(), "expired token should be rejected");
}

#[test]
fn hmac_signature_is_deterministic() {
    let signer = TokenSigner::new(SIGNING_KEY).expect("valid signer");
    let repository = RepositoryScope::new(RepositoryProvider::GitHub, "team", "repo", Some("main"))
        .expect("valid scope");
    let claims_a = TokenClaims::new(
        "issuer",
        "subject",
        TokenScope::Read,
        repository.clone(),
        42,
    )
    .expect("valid claims");
    let claims_b = TokenClaims::new("issuer", "subject", TokenScope::Read, repository, 42)
        .expect("valid claims");

    let token_a = signer.sign(&claims_a).expect("signing should succeed");
    let token_b = signer.sign(&claims_b).expect("signing should succeed");

    assert_eq!(token_a, token_b, "HMAC signatures should be deterministic");
}

#[test]
fn repository_scope_roundtrips_through_token_claims() {
    let signer = TokenSigner::new(SIGNING_KEY).expect("valid signer");
    let scope = RepositoryScope::new(
        RepositoryProvider::GitLab,
        "group",
        "project",
        Some("refs/heads/dev"),
    )
    .expect("valid scope");
    let claims =
        TokenClaims::new("issuer", "user", TokenScope::Write, scope, 999).expect("valid claims");

    let token = signer.sign(&claims).expect("signing should succeed");
    let verified = signer
        .verify_at(&token, 0)
        .expect("verification should succeed");

    assert_eq!(verified.repository().provider(), RepositoryProvider::GitLab);
    assert_eq!(verified.repository().owner(), "group");
    assert_eq!(verified.repository().name(), "project");
    assert_eq!(verified.repository().revision(), Some("refs/heads/dev"));
    assert_eq!(verified.scope(), TokenScope::Write);
}

use std::{io::Error as IoError, num::TryFromIntError};

use shardline_index::{
    FileRecordInvariantError, LocalIndexStoreError, MemoryIndexStoreError, MemoryRecordStoreError,
    PostgresMetadataStoreError,
};
use shardline_protocol::HashParseError;
use shardline_server_core::{InvalidSerializedShardError, ServerObjectStoreError};
use shardline_storage::{LocalObjectStoreError, S3ObjectStoreError};
use thiserror::Error;

use crate::xorb::XorbParseError;

/// Xet adapter failure.
#[derive(Debug, Error)]
pub enum XetAdapterError {
    /// Local storage IO failed.
    #[error("local storage operation failed")]
    Io(#[from] IoError),
    /// Numeric conversion exceeded supported bounds.
    #[error("numeric conversion exceeded supported bounds")]
    NumericConversion(#[from] TryFromIntError),
    /// Hash parsing failed.
    #[error("invalid content hash")]
    HashParse(#[from] HashParseError),
    /// Object-storage adapter access failed.
    #[error("object storage adapter operation failed")]
    ObjectStore(#[from] ServerObjectStoreError),
    /// Local object-storage adapter access failed.
    #[error("local object storage operation failed")]
    LocalObjectStore(#[from] LocalObjectStoreError),
    /// S3-compatible object-storage adapter access failed.
    #[error("s3 object storage operation failed")]
    S3ObjectStore(#[from] S3ObjectStoreError),
    /// Index adapter access failed.
    #[error("index adapter operation failed")]
    IndexStore(#[from] LocalIndexStoreError),
    /// In-memory index adapter access failed.
    #[error("memory index adapter operation failed")]
    MemoryIndexStore(#[from] MemoryIndexStoreError),
    /// In-memory record adapter access failed.
    #[error("memory record adapter operation failed")]
    MemoryRecordStore(#[from] MemoryRecordStoreError),
    /// Postgres metadata adapter access failed.
    #[error("postgres metadata adapter operation failed")]
    PostgresMetadata(#[from] PostgresMetadataStoreError),
    /// Stored file metadata could not produce a valid reconstruction plan.
    #[error("stored file metadata was invalid")]
    FileRecordInvariant(#[from] FileRecordInvariantError),
    /// A content hash was malformed.
    #[error("content hash must be 64 hexadecimal characters")]
    InvalidContentHash,
    /// The xorb transfer path prefix was unsupported.
    #[error("xorb transfer prefix must be default")]
    InvalidXorbPrefix,
    /// The uploaded xorb bytes did not match the requested hash.
    #[error("xorb body hash did not match the requested path hash")]
    XorbHashMismatch,
    /// The uploaded xorb bytes were not a valid serialized xorb object.
    #[error("xorb body was not a valid serialized xorb object")]
    InvalidSerializedXorb,
    /// The uploaded shard bytes were not a valid serialized shard object.
    #[error("shard body was not a valid serialized shard object")]
    InvalidSerializedShard(#[from] InvalidSerializedShardError),
    /// A shard upload referenced a missing xorb.
    #[error("shard referenced a missing xorb")]
    MissingReferencedXorb,
    /// Shard metadata exceeded bounded parser safety limits.
    #[error("shard metadata exceeded bounded parser safety limits")]
    TooManyShardTerms,
    /// Requested content was not found.
    #[error("content not found")]
    NotFound,
    /// Arithmetic overflowed a checked bound.
    #[error("arithmetic overflow")]
    Overflow,
    /// The reconstruction range start exceeded the end of the file.
    #[error("requested range is not satisfiable")]
    RangeNotSatisfiable,
}

impl From<XorbParseError> for XetAdapterError {
    fn from(value: XorbParseError) -> Self {
        match value {
            XorbParseError::HashMismatch => Self::XorbHashMismatch,
            XorbParseError::InvalidFormat(_)
            | XorbParseError::NumericConversion(_)
            | XorbParseError::Io(_) => Self::InvalidSerializedXorb,
        }
    }
}

use shardline_index::parse_xet_hash_hex;

use crate::error::XetAdapterError;

pub const XORB_TRANSFER_NAMESPACE: &str = "default";
pub const XORB_TRANSFER_ROUTE: &str = "/transfer/xorb/{prefix}/{hash}";
pub const XET_READ_TOKEN_ROUTE: &str = "/api/{provider}/{owner}/{repo}/xet-read-token/{rev}";
pub const XET_WRITE_TOKEN_ROUTE: &str = "/api/{provider}/{owner}/{repo}/xet-write-token/{rev}";

/// # Errors
///
/// Returns an error when the hash is not valid hex.
pub fn validate_hash_path(value: &str) -> Result<(), XetAdapterError> {
    parse_xet_hash_hex(value)?;
    Ok(())
}

/// # Errors
///
/// Returns an error when the provided hash is not valid hex.
pub fn validate_optional_content_hash(content_hash: Option<&str>) -> Result<(), XetAdapterError> {
    if let Some(content_hash) = content_hash {
        validate_hash_path(content_hash)?;
    }

    Ok(())
}

/// # Errors
///
/// Returns an error when the prefix does not match the expected transfer namespace.
pub fn validate_xorb_transfer_namespace(prefix: &str) -> Result<(), XetAdapterError> {
    if prefix != XORB_TRANSFER_NAMESPACE {
        return Err(XetAdapterError::InvalidXorbPrefix);
    }

    Ok(())
}

#[must_use]
pub fn build_xorb_transfer_url(public_base_url: &str, hash_hex: &str) -> String {
    let trimmed_base_url = public_base_url.trim_end_matches('/');
    let mut url = String::with_capacity(
        trimmed_base_url
            .len()
            .saturating_add("/transfer/xorb/default/".len())
            .saturating_add(hash_hex.len()),
    );
    url.push_str(trimmed_base_url);
    url.push_str("/transfer/xorb/");
    url.push_str(XORB_TRANSFER_NAMESPACE);
    url.push('/');
    url.push_str(hash_hex);
    url
}

#[cfg(test)]
