                            range_end: 1,
                            packed_start: 0,
                            packed_end: 4,
                        }],
                    },
                    None,
                );
                assert!(response.is_ok());
                let Ok(response) = response else {
                    return;
                };
                response
            }),
            ("b".repeat(64), {
                let response = build_reconstruction_response(
                    "http://127.0.0.1:8080",
                    &FileRecord {
                        file_id: "asset-b".to_owned(),
                        content_hash: "b".repeat(64),
                        total_bytes: 4,
                        chunk_size: 4,
                        repository_scope: None,
                        chunks: vec![FileChunkRecord {
                            hash: "c".repeat(64),
                            offset: 0,
                            length: 4,
                            range_start: 0,
                            range_end: 1,
                            packed_start: 0,
                            packed_end: 4,
