        let h2 = DataHash::from_hex(&hex).unwrap();
        prop_assert_eq!(h, h2);
    }

    #[test]
    fn data_hash_u8_roundtrip(arr in prop::array::uniform32(0u8..=255)) {
        let h = DataHash::from(arr);
        let back: [u8; 32] = h.into();
        prop_assert_eq!(arr, back);
    }
}

