    // Verify gone
    let get_gone = client
        .get(format!("{base_url}/v1/lfs/objects/{oid}"))
        .header("Authorization", format!("Bearer {token}"))
        .send()
        .await
        .unwrap();
    assert_eq!(get_gone.status(), 404, "deleted object should be gone");

    // Re-upload same content
    let reupload = client
        .put(format!("{base_url}/v1/lfs/objects/{oid}"))
        .header("Authorization", format!("Bearer {token}"))
