    let config_digest = format!("sha256:{}", hex::encode(sha2::Sha256::digest(config)));
    client
        .post(format!("{base_url}/v2/{repo}/blobs/uploads?digest={config_digest}"))
        .header("Authorization", format!("Bearer {token}"))
        .body(config.to_vec())
        .send()
