        .post(format!("{base_url}/api/models/test-owner/test-model/webhooks"))
        .header("Authorization", format!("Bearer {token}"))
        .json(&serde_json::json!({
            "url": "https://example.com/webhook",
            "events": ["push", "delete"],
            "secret": "my-secret"
        }))
        .send()
        .await
