fn git_stdout_with_home<const N: usize>(
    repo: &Path,
    home: &Path,
    args: [&str; N],
) -> Result<String, TestError> {
    let mut command = Command::new("git");
    with_test_home(&mut command, home)
        .current_dir(repo)
