        .body(blob_bytes.as_slice().to_vec())
        .send()
        .await?;
    assert_eq!(blob_upload.status(), StatusCode::CREATED);

    let blob_head = client
        .head(format!(
            "{}/v2/team/assets/blobs/sha256:{blob_digest}",
