        .bearer_auth(&read_token)
        .header("Range", "bytes=2-5")
        .send()
        .await?;
    assert_eq!(blob_range.status(), StatusCode::PARTIAL_CONTENT);
    assert_eq!(
        blob_range
            .headers()
            .get("Content-Range")
            .and_then(|value| value.to_str().ok()),
