    );
    assert_eq!(blob_range.bytes().await?.as_ref(), b"cdef");

    let manifest_bytes = serde_json::to_vec(&json!({
        "schemaVersion": 2,
        "mediaType": "application/vnd.oci.image.manifest.v1+json",
