    )?;
    let child_manifest_b_digest = seed_oci_manifest(
        &runtime,
        "team/assets",
        &repository_scope,
        "application/vnd.oci.image.manifest.v1+json",
        &child_manifest_b,
    )?;

    let index_bytes = serde_json::to_vec(&json!({
        "schemaVersion": 2,
        "mediaType": "application/vnd.oci.image.index.v1+json",
        "manifests": [{
