            },
            "layers": [],
        }))?;
        let response = client
            .put(format!(
                "{}/v2/team/assets/manifests/{tag}",
                runtime.base_url()
            ))
            .bearer_auth(&write_token)
            .header(CONTENT_TYPE, "application/vnd.oci.image.manifest.v1+json")
            .body(manifest)
            .send()
            .await?;
        assert_eq!(response.status(), StatusCode::CREATED);
    }

    let first_page = client
        .get(format!(
