    let patch = client
        .patch(&upload_url)
        .bearer_auth(&write_token)
        .header(CONTENT_RANGE, "0-3")
        .body(b"abcd".to_vec())
        .send()
        .await?;
    assert_eq!(patch.status(), StatusCode::ACCEPTED);

    let blob_bytes = b"abcdefgh";
