    );
    upload_repository_asset(&runtime, RepositoryProvider::Generic, "team", "assets").await?;

    let webhook_body = br#"{
            "kind":"repository_deleted",
            "repository":{"owner":"team","name":"assets"}
        }"#;
    let response = Client::new()
        .post(format!(
            "{}/v1/providers/generic/webhooks",
