        ))
        .header("x-shardline-event", "repository_deleted")
        .header("x-shardline-delivery", "delivery-1")
        .header(
            "x-shardline-signature",
            generic_webhook_signature(webhook_body).unwrap_or_else(|| "sha256=".to_owned()),
        )
        .body(webhook_body.to_vec())
        .send()
        .await?;
